NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Joshua'

CHAPTERS = {
    1: {
        1: 'Torej po smrti Mojzesa, Gospodovega služabnika, se je pripetilo, da je Gospod spregovoril Nunovemu sinu Józuetu, Mojzesovemu služabniku, rekoč:',
        2: '»Moj služabnik Mojzes je mrtev. Sedaj torej vstani, pojdi čez ta Jordan, ti in vse to ljudstvo, v deželo, ki jo dajem njim, torej Izraelovim otrokom.',
        3: 'Vsak kraj, na katerega bo stopil podplat tvojega stopala, to sem ti dal, kakor sem rekel Mojzesu.',
        4: 'Od divjine in tega Libanona, celo do velike reke, reke Evfrat, vso deželo Hetejcev in do velikega morja proti zahajanju sonca, bo vaša pokrajina.',
        5: 'Tam noben mož ne bo zmožen obstati pred teboj vse dni tvojega življenja. Kakor sem bil z Mojzesom, tako bom s teboj. Ne bom te razočaral niti te ne bom zapustil.',
        6: 'Bodi močan in odločnega poguma, kajti temu ljudstvu boš v dediščino razdelil deželo, za katero sem prisegel njihovim očetom, da jim jo dam.',
        7: 'Samo močan bodi in zelo pogumen, da boš lahko obeležil, da storiš glede na vso postavo, ki ti jo je moj služabnik Mojzes zapovedal. Ne obrni se od nje ne k desni roki ne k levi, da boš lahko uspeval kamorkoli greš.',
        8: 'Ta knjiga postave ne bo odšla od tvojih ust, temveč boš o njej premišljeval podnevi in ponoči, da boš lahko obeležil, da storiš glede na vse to, kar je zapisano v njej, kajti takrat boš naredil svojo pot uspešno in takrat boš imel dober uspeh.',
        9: 'Mar ti nisem jaz zapovedal? Bodi močan in odločnega poguma. Ne bodi prestrašen niti ne bodi zaprepaden, kajti Gospod, tvoj Bog, je s teboj, kamorkoli greš.«',
        10: 'Potem je Józue zapovedal častnikom ljudstva, rekoč:',
        11: '»Preidite skozi vojsko in zapovejte ljudstvu, rekoč: ›Pripravite svoj živež, kajti v treh dneh boste šli preko tega Jordana, da vstopite, da vzamete v last deželo, ki vam jo daje Gospod, vaš Bog, da jo vzamete v last.‹«',
        12: 'Rubenovcem in Gádovcem in polovici Manásejevega rodu pa je Józue spregovoril, rekoč:',
        13: '»Spomnite se besede, ki vam jo je zapovedal Gospodov služabnik Mojzes, rekoč: › Gospod, vaš Bog, vam je dal počitek in vam je dal to deželo.‹',
        14: 'Vaše žene, vaši malčki in vaša živina bodo ostali v deželi, ki vam jo je dal Mojzes na tej strani Jordana, toda vi boste pred vašimi brati prečkali oboroženi, vsi močni junaški možje in jim pomagali,',
        15: 'dokler Gospod ne da vašim bratom počitek, kakor ga je dal vam in tudi oni ne vzamejo v last dežele, ki jim jo daje Gospod, vaš Bog. Potem se boste vrnili v deželo svoje posesti in jo uživali, ki vam jo je dal Gospodov služabnik Mojzes na tej strani Jordana, proti sončnemu vzhodu.«',
        16: 'Józuetu so odgovorili, rekoč: »Vse, kar nam zapoveduješ, bomo storili in kamor nas pošlješ, bomo šli.',
        17: 'Glede na to, kakor smo Mojzesu prisluhnili v vseh stvareh, tako bomo prisluhnili tebi. Samo Gospod, tvoj Bog, naj bo s teboj, kakor je bil z Mojzesom.',
        18: 'Kdorkoli je ta, ki se upre zoper tvojo zapoved in ne bo prisluhnil tvojim besedam v vsem, kar mu zapoveš, bo usmrčen. Samo močan bodi in odločnega poguma.«',
    },
    2: {
        1: 'Nunov sin Józue je iz Šitíma na skrivaj poslal ogledovat dva moža, rekoč: »Pojdita, poglejta deželo, celo Jeriho.« Odšla sta ter prišla v hišo pocestnice, po imenu Rahába in tam prenočila.',
        2: 'Kralju Jerihe je bilo povedano, rekoč: »Glej, nocoj sta prišla sèm moža izmed Izraelovih otrok, da preiščeta deželo.«',
        3: 'Kralj Jerihe je poslal k Rahábi, rekoč: »Privedi naprej moža, ki sta prišla k tebi, ki sta vstopila v tvojo hišo, kajti prišla sta, da bi preiskala vso deželo.«',
        4: 'Ženska je vzela dva moža ter ju skrila in rekla tako: »K meni sta prišla moža, toda nisem vedela od kod sta bila.',
        5: 'Pripetilo se je okoli časa zapiranja velikih vrat, ko je bilo temno, da sta moža odšla ven. Kam sta moža odšla, ne vem. Hitro ju zasledujte, kajti dohiteli ju boste.«',
        6: 'Toda ona ju je privedla gor na streho hiše in ju skrila s stebli lana, ki jih je razvrstila po strehi.',
        7: 'Možje so ju zasledovali po poti k Jordanu, k prehodom in takoj, ko so tisti, ki so ju zasledovali, odšli ven, so zaprli velika vrata.',
        8: 'Preden sta se ulegla, je prišla k njima na streho',
        9: 'in možema rekla: »Vem, da vam je Gospod dal to deželo in da je vaša strahota padla na nas in da vsi prebivalci dežele zaradi vas slabijo.',
        10: 'Kajti slišali smo, kako je Gospod za vas posušil vode Rdečega morja, ko ste prišli iz Egipta, in kaj ste storili dvema kraljema Amoréjcev, ki sta bila na drugi strani Jordana, Sihónu in Ogu, ki ste jih popolnoma uničili.',
        11: 'Takoj, ko smo slišali te stvari, so se naša srca stopila niti tam zaradi vas ni ostalo nič več poguma v kateremkoli človeku, kajti Gospod, vaš Bog, on je Bog v nebesih zgoraj in na zemlji spodaj.',
        12: 'Zdaj torej, prosim vaju, prisezita mi pri Gospodu, ker sem vama izkazala prijaznost, da bosta tudi vidva izkazala prijaznost hiši mojega očeta in mi dala zanesljivo znamenje.',
        13: 'In da boste mojega očeta rešili živega in mojo mater, moje brate, moje sestre in vse, kar imajo in naša življenja osvobodili pred smrtjo.«',
        14: 'Moža sta ji odgovorila: »Najina življenja za vaša, če ne izustiš te naše stvari. Zgodilo se bo, ko nam Gospod da deželo, da bomo s teboj postopali prijazno in zvesto.«',
        15: 'Potem ju je po vrvi spustila skozi okno, kajti njena hiša je bila na mestnem obzidju in prebivala je na obzidju.',
        16: 'Rekla jima je: »Spravita se do gore, da vaju ne bi srečali zasledovalci in tam se skrivajta tri dni, dokler se zasledovalci ne vrnejo in potem lahko gresta svojo pot.«',
        17: 'Moža sta ji rekla: »Midva bova brez krivde glede te tvoje prisege, s katero si naju prisegla.',
        18: 'Glej, ko pridemo v deželo, boš to škrlatno vrv privezala na okno, skozi katero si naju spustila dol in domov k sebi boš privedla svojega očeta, svojo mater, svoje brate in vso družino svojega očeta.',
        19: 'In zgodilo se bo, da kdorkoli bo šel ven skozi vrata tvoje hiše na ulico, bo njegova kri na njegovi glavi, midva pa bova brez krivde. In kdorkoli bo s teboj v hiši, njegova kri bo na najini glavi, če bo katerakoli roka nad njim.',
        20: 'Če izustiš to našo stvar, potem bova prosta tvoje prisege, s katero si naju primorala priseči.«',
        21: 'Rekla je: »Glede na vajine besede, tako naj bo to.« Poslala ju je proč in sta odšla in na okno je privezala škrlatno vrv.',
        22: 'Odšla sta in prišla h gori ter tam ostala tri dni, dokler se zasledovalci niso vrnili. Zasledovalci so ju iskali po vsej poti, toda niso ju našli.',
        23: 'Tako sta se oba moža vrnila in spustila z gore, šla čez in prišla k Nunovemu sinu Józuetu in mu povedala vse stvari, ki so se jima pripetile.',
        24: 'Józuetu sta rekla: »Resnično, Gospod je v naše roke izročil vso deželo, kajti celo vsi prebivalci dežele zaradi nas slabijo.«',
    },
    3: {
        1: 'Józue je zgodaj zjutraj vstal in odpravili so se iz Šitíma ter prišli k Jordanu, on in vsi Izraelovi otroci in tam so prenočili, preden so šli čez.',
        2: 'Po treh dneh se je pripetilo, da so častniki šli skozi vojsko',
        3: 'in zapovedali ljudstvu, rekoč: »Ko zagledate skrinjo zaveze Gospoda, svojega Boga in duhovnike in Lévijevce, ki jo nosijo, potem se boste odpravili iz svojega kraja in šli za njo.',
        4: 'Vendar naj bo med vami in njo prazen prostor, okoli dva tisoč komolcev po meri. Ne pridite bliže k njej, da boste lahko poznali pot, po kateri morate iti, kajti poprej še niste šli po tej poti.«',
        5: 'Józue je rekel ljudstvu: »Posvetite se, kajti jutri bo Gospod med vami delal čudeže.«',
        6: 'Duhovnikom je Józue spregovoril, rekoč: »Dvignite skrinjo zaveze in pojdite čez pred ljudstvom.« In dvignili so skrinjo zaveze in odšli pred ljudstvom.',
        7: 'Gospod je rekel Józuetu: »Ta dan te bom začel poveličevati pred očmi vsega Izraela, da bodo lahko vedeli, da kakor sem bil z Mojzesom, tako bom s teboj.',
        8: 'Duhovnikom, ki nosijo skrinjo zaveze, boš zapovedal, rekoč: ›Ko pridete k robu jordanske vode, boste mirno stali v Jordanu.‹«',
        9: 'Izraelovim otrokom je Józue rekel: »Pridite sèm in prisluhnite besedam Gospoda, svojega Boga.«',
        10: 'Józue je rekel: »S tem boste spoznali, da je med vami živi Bog in da bo on čisto gotovo pred vami napodil Kánaance, Hetejce, Hivéjce, Perizéjce, Girgašéjce, Amoréjce in Jebusejce.',
        11: 'Glejte, skrinja zaveze Gospoda vse zemlje, gre preko, pred vami, v Jordan.',
        12: 'Zdaj torej vzemite dvanajst mož izmed Izraelovih rodov, iz vsakega rodu moža.',
        13: 'Zgodilo se bo, takoj ko bodo podplati stopal duhovnikov, ki nosijo skrinjo Gospoda, Gospoda vse zemlje, počivali v vodah Jordana, da bodo vode Jordana odrezane od vod, ki prihajajo dol od zgoraj in bodo stale na kupu.«',
        14: 'In pripetilo se je, ko se je ljudstvo odpravilo od svojih šotorov, da gredo čez Jordan, in so duhovniki pred ljudstvom nosili skrinjo zaveze',
        15: 'in ko so tisti, ki so nosili skrinjo, prišli k Jordanu in so bila stopala duhovnikov, ki so nosili skrinjo, omočena v rob vode (kajti Jordan ves čas žetve preplavlja vse svoje bregove),',
        16: 'da so vode, ki so prihajale dol od zgoraj, stale in se vzdignile na kup, zelo daleč od mesta Adám, ki je poleg Caretána. Tiste, ki so prihajale dol k morju ravnine, torej slanemu morju, so odtekle in bile odrezane in ljudstvo je šlo čez prav nasproti Jerihi.',
        17: 'Duhovniki, ki so nosili skrinjo Gospodove zaveze, so trdno stali na suhih tleh v sredi Jordana in vsi Izraelci so šli čez po suhih tleh, dokler ni vse ljudstvo šlo čez Jordan.',
    },
    4: {
        1: 'Pripetilo se je, ko je vse ljudstvo dokončalo prehod čez Jordan, da je Gospod spregovoril Józuetu, rekoč:',
        2: '»Vzemi dvanajst mož izmed ljudstva, iz vsakega rodu moža',
        3: 'in jim zapovej, rekoč: ›Iz srede Jordana, iz kraja, kjer so trdno stala stopala duhovnikov, vzemite dvanajst kamnov in odnesli jih boste s seboj prek [Jordana] in jih pustili na kraju za nastanitev, kjer boste to noč prenočili.‹«',
        4: 'Potem je Józue poklical dvanajst mož, ki jih je postavil izmed Izraelovih otrok, iz vsakega rodu moža',
        5: 'in Józue jim je rekel: »Pojdite čez pred skrinjo Gospoda, svojega Boga, v sredo Jordana in vsak izmed vas naj na svojo ramo vzame kamen, glede na število rodov Izraelovih otrok,',
        6: 'da bo to lahko znamenje med vami, da ko vaši otroci vprašajo svoje starše, v času, ki pride, rekoč: ›Kaj mislite s temi kamni?‹',
        7: 'Potem jim boste odgovorili: ›Da so bile vode Jordana odrezane pred skrinjo Gospodove zaveze. Ko je ta šla čez Jordan, so bile jordanske vode odsekane in ti kamni bodo Izraelovim otrokom v spomin na veke.‹«',
        8: 'Izraelovi otroci so storili, kakor je Józue zapovedal in iz srede Jordana vzeli dvanajst kamnov, kakor je Gospod govoril Józuetu, glede na število rodov Izraelovih otrok in jih s seboj odnesli preko [Jordana] na kraj, kjer so prenočili in tam so jih odložili.',
        9: 'Józue je dvanajst kamnov postavil v sredo Jordana, na kraj, kjer so stala stopala duhovnikov, ki so nosili skrinjo zaveze in tam so do današnjega dne.',
        10: 'Kajti duhovniki, ki so nosili skrinjo, so stali v sredi Jordana, dokler ni bila končana vsaka stvar, ki jo je Gospod zapovedal Józuetu, da spregovori ljudstvu, glede na vse, kar je Mojzes zapovedal Józuetu in ljudstvo je pohitelo in šlo čez.',
        11: 'Pripetilo se je, ko je vse ljudstvo dokončalo prehod čez [Jordan], da je šla čez skrinja in duhovniki v prisotnosti ljudstva.',
        12: 'Rubenovi otroci, Gadovi otroci in polovica Manásejevega rodu so oboroženi šli čez pred Izraelovimi otroki, kakor jim je govoril Mojzes.',
        13: 'Okoli štirideset tisoč pripravljenih za vojno je šlo čez pred Gospodom v bitko k ravninam Jerihe.',
        14: 'Na ta dan je Gospod poveličal Józueta v očeh vsega Izraela in oni so se ga bali, kakor so se bali Mojzesa, vse dni njegovega življenja.',
        15: 'Gospod je spregovoril Józuetu, rekoč:',
        16: '»Zapovej duhovnikom, ki nosijo skrinjo pričevanja, da pridejo gor, ven iz Jordana.«',
        17: 'Józue je torej zapovedal duhovnikom, rekoč: »Pridite gor iz Jordana.«',
        18: 'Pripetilo se je, ko so duhovniki, ki so nosili skrinjo Gospodove zaveze, prišli gor iz srede Jordana in so bili podplati duhovniških stopal dvignjeni na suho zemljo, da so se vode Jordana vrnile na svoj kraj in stekle čez vse svoje bregove, kakor so počele poprej.',
        19: 'In ljudstvo je prišlo gor iz Jordana na deseti dan prvega meseca ter se utaborilo v Gilgálu, na vzhodni meji Jerihe.',
        20: 'Tistih dvanajst kamnov, ki so jih vzeli iz Jordana, je Józue postavil v Gilgálu.',
        21: 'Izraelovim otrokom je spregovoril, rekoč: »Ko bodo vaši otroci vprašali svoje očete, v času, ki pride, rekoč: ›Kaj pomenijo ti kamni?‹',
        22: 'Potem boste svojim otrokom dali vedeti, rekoč: ›Izrael je po suhih tleh prešel preko tega Jordana.',
        23: 'Kajti Gospod, vaš Bog, je izpred vas posušil vode Jordana, dokler niste prešli čez, kakor je Gospod, vaš Bog, storil Rdečemu morju, ki ga je posušil pred nami, dokler nismo prešli čez,',
        24: 'da bi vsa ljudstva zemlje lahko poznala Gospodovo roko, da je ta mogočna, da se boste lahko na veke bali Gospoda, svojega Boga.‹«',
    },
    5: {
        1: 'Pripetilo se je, ko so vsi kralji Amoréjcev, ki so bili na zahodni strani Jordana in vsi kralji Kánaancev, ki so bili poleg morja, slišali, da je Gospod izpred Izraelovih otrok posušil vode Jordana, dokler nismo prešli čez, da se je njihovo srce stopilo niti ni bilo več tam v njih duha zaradi Izraelovih otrok.',
        2: 'Ob tistem času je Gospod rekel Józuetu: »Naredi si ostre nože in ponovno, drugič, obreži Izraelove otroke.«',
        3: 'Józue si je naredil ostre nože in Izraelove otroke obrezal na hribu prednjih kožic.',
        4: 'In to je razlog, zakaj je Józue obrezal. Vse ljudstvo, ki je prišlo iz Egipta, kar jih je bilo moških, torej vsi bojevniki, so umrli po poti v divjini, potem ko so prišli iz Egipta.',
        5: 'Torej vse ljudstvo, ki je izšlo, je bilo obrezano. Toda vsega ljudstva, ki je bilo rojeno po poti v divjini, ko so izšli iz Egipta, njih niso obrezali.',
        6: 'Kajti Izraelovi otroci so štirideset let hodili po divjini, dokler ni bilo vse ljudstvo, ki so bili bojevniki, ki so prišli iz Egipta, použito, ker niso ubogali Gospodovega glasu, katerim je Gospod prisegel, da jim ne bo pokazal dežele, ki jo je Gospod prisegel njihovim očetom, da nam jo bo dal, deželo, kjer tečeta mleko in med.',
        7: 'Njihove otroke, ki jih je dvignil namesto njih, te je Józue obrezal, kajti bili so neobrezani, ker jih po poti niso obrezali.',
        8: 'Pripetilo se je, ko so naredili obrezo vsega ljudstva, da so ostali na svojih prostorih v taboru, dokler niso okrevali.',
        9: 'Gospod je rekel Józuetu: »Danes sem od tebe odvalil egiptovsko grajo.« Zaradi tega se ime kraja imenuje Gilgál do današnjega dne.',
        10: 'Izraelovi otroci so se utaborili v Gilgálu in na štirinajsti dan meseca zvečer praznovali pasho na ravninah Jerihe.',
        11: 'Naslednji dan po pashi so jedli od starega žita dežele, nekvašene kolače in praženo žito, na prav isti dan.',
        12: 'Mana je prenehala naslednji dan, potem ko so jedli od starega žita dežele niti Izraelovi otroci niso imeli več mane, temveč so tisto leto jedli od sadov kánaanske dežele.',
        13: 'Pripetilo se je, ko je bil Józue pri Jerihi, da je povzdignil svoje oči in pogledal in glej, nasproti njega je stal mož z izvlečenim mečem v svoji roki. Józue je odšel k njemu ter mu rekel: » Ali si za nas ali za naše nasprotnike?«',
        14: 'Odgovoril je: »Ne, temveč kot poveljnik Gospodove vojske; sedaj sem prišel.« Józue je padel na svoj obraz k zemlji in oboževal ter mu rekel: »Kaj pravi moj gospod svojemu služabniku?«',
        15: 'Poveljnik Gospodove vojske je Józuetu rekel: »Sezuj svoj čevelj s svojega stopala, kajti kraj, na katerem stojiš, je svet.« In Józue je storil tako.',
    },
    6: {
        1: 'Torej Jeriha je bila strogo zaprta zaradi Izraelovih otrok. Nihče ni odšel ven in nihče ni prišel noter.',
        2: 'Gospod je rekel Józuetu: »Poglej, v tvojo roko sem izročil Jeriho in njenega kralja in močne junaške može.',
        3: 'Obdali boste mesto, vsi vi bojevniki in enkrat obhodili mesto. Tako boste počeli šest dni.',
        4: 'Sedem duhovnikov bo pred skrinjo nosilo sedem šofarjev iz ovnovih rogov, in sedmi dan boste sedemkrat obkrožili mesto in duhovniki bodo zatrobili s šofarji.',
        5: 'In zgodilo se bo, da ko bodo z ovnovim rogom naredili dolgo trobljenje in ko zaslišite zvok šofarja, naj vse ljudstvo zavpije z velikim krikom in mestno obzidje bo plosko padlo dol in ljudstvo se bo povzpelo, vsak človek naravnost pred seboj.«',
        6: 'Nunov sin Józue je poklical duhovnike ter jim rekel: »Vzdignite skrinjo zaveze in sedem duhovnikov naj pred Gospodovo skrinjo nosi sedem šofarjev iz ovnovih rogov.«',
        7: 'Ljudstvu pa je rekel: »Pojdite naprej in obkrožite mesto in naj tisti, ki je oborožen, gre naprej pred Gospodovo skrinjo.«',
        8: 'Pripetilo se je, ko je Józue govoril ljudstvu, da je sedem duhovnikov, nosečih sedem šofarjev iz ovnovih rogov, šlo naprej pred Gospodom in trobilo s šofarji in skrinja Gospodove zaveze jim je sledila.',
        9: 'Oboroženi možje so šli pred duhovniki, ki so trobili na šofarje in zadnja straža je prišla za skrinjo. Duhovniki pa so hodili in trobili s šofarji.',
        10: 'Józue je zapovedal ljudstvu, rekoč: »Ne boste kričali niti naredili nobenega hrupa z vašim glasom niti ne bo nobena beseda izšla iz vaših ust do dneva, ko vam zapovem kričati; potem boste kričali.«',
        11: 'Tako je Gospodova skrinja obkrožila mesto, ga enkrat obhodila in prišli so v tabor in prenočili v taboru.',
        12: 'Józue je vstal zgodaj zjutraj in duhovniki so dvignili Gospodovo skrinjo.',
        13: 'Sedem duhovnikov, ki so pred Gospodovo skrinjo nosili sedem šofarjev iz ovnovih rogov, je nenehno hodilo naprej in trobilo s šofarji in oboroženi možje so šli pred njimi, toda zadnja straža je prišla za Gospodovo skrinjo, duhovniki hodeč naprej in trobeč s šofarji.',
        14: 'Drugi dan so enkrat obkrožili mesto in se vrnili v tabor. Tako so počeli šest dni.',
        15: 'Na sedmi dan se je pripetilo, da so vstali zgodaj, ob jutranjem svitanju in na isti način sedemkrat obkrožili mesto. Samo ta dan so mesto obkrožili sedemkrat.',
        16: 'Pripetilo se je sedmič, ko so duhovniki zatrobili s šofarji, da je Józue rekel ljudstvu: »Kričite, kajti Gospod vam je dal mesto.',
        17: 'Mesto bo prekleto Gospodu, celó to in vse, kar je v njem. Samo pocestnica Rahába bo živela, ona in vsi, ki so z njo v hiši, ker je skrila poslanca, ki smo ju poslali.',
        18: 'Vi pa se zagotovo zadržite pred prekleto stvarjo, da se ne bi naredili preklete, ko vzamete od preklete stvari in naredite tabor Izraelcev prekletstvo in ga vznemirite.',
        19: 'Toda vse srebro, zlato in posode iz brona in železa so posvečeni Gospodu. Pridejo naj v Gospodovo zakladnico.«',
        20: 'Tako je ljudstvo zakričalo, ko so duhovniki zatrobili s šofarji in pripetilo se je, ko je ljudstvo zaslišalo zvok šofarja in je ljudstvo zavpilo z velikim krikom, da je obzidje plosko padlo dol, tako da je ljudstvo odšlo gor v mesto, vsak mož naravnost pred seboj in zavzeli so mesto.',
        21: 'Popolnoma so uničili vse, kar je bilo v mestu, tako moškega kakor žensko, mladega, starega, vola, ovco in osla, z ostrino meča.',
        22: 'Toda Józue je rekel dvema možema, ki sta ogledovala deželo: »Pojdita v hišo pocestnice in od tam privedita žensko in vse, kar ima, kakor sta ji prisegla.«',
        23: 'Mladeniča, ki sta bila oglednika, sta vstopila in privedla ven Rahábo, njenega očeta, njeno mater, njene brate in vse, kar je imela in ven sta privedla vse njeno sorodstvo in jih pustila zunaj tabora Izraelcev.',
        24: 'Mesto pa so požgali z ognjem in vse, kar je bilo v njem. Samo srebro, zlato in posode iz brona in iz železa, so dali v zakladnico Gospodove hiše.',
        25: 'Józue je rešil pocestnico Rahábo živo in družino njenega očeta in vse, kar je imela. V Izraelu prebiva do današnjega dne, ker je skrila poslanca, ki ju je Józue poslal, da ogledata Jeriho.',
        26: 'Ob tistem času jih je Józue zaprisegel, rekoč: »Preklet bodi mož pred Gospodom, ki dvigne in pozida to mesto Jeriho. Njen temelj bo položil v svojem prvorojencu in v njegovem najmlajšem sinu bo postavil njena velika vrata.«',
        27: 'Tako je bil Gospod z Józuetom in njegova slava je bila razglašena po vsej deželi.',
    },
    7: {
        1: 'Toda Izraelovi otroci so zagrešili prekršek v prekleti stvari, kajti Ahán, sin Karmíja, sin Zabdíja, sin Zeraha, iz Judovega rodu, je vzel od preklete stvari in Gospodova jeza je bila vžgana zoper Izraelove otroke.',
        2: 'Józue je poslal može iz Jerihe v Aj, ki je poleg Bet Avena, na vzhodni strani Betela in jim spregovoril, rekoč: »Pojdite gor in poglejte deželo.« Možje so odšli gor in pogledali Aj.',
        3: 'Vrnili so se k Józuetu in mu rekli: »Naj ne gre gor vse ljudstvo; temveč naj gre gor okoli dva ali tri tisoč mož in naj udarijo Aj; in ne primoraj vsega ljudstva, da se trudi tja, kajti le malo jih je.«',
        4: 'Tako jih je odšlo tja gor izmed ljudstva okoli tri tisoč mož, in ti so pobegnili pred možmi iz Aja.',
        5: 'Možje iz Aja so jih izmed njih udarili šestintrideset mož, kajti pregnali so jih izpred velikih vrat, celó do Šebaríma in jih udarili pri hitenju dol, zato so se srca ljudstva stopila in postala kakor voda.',
        6: 'Józue je pred Gospodovo skrinjo raztrgal svoja oblačila in padel na svoj obraz k zemlji do večera, on in Izraelove starešine in na svoje glave so si posuli prah.',
        7: 'Józue je rekel: »Ojoj, oh Gospod Bog, čemu si to ljudstvo sploh privedel čez Jordan, da nas izročiš v roko Amoréjcev, da nas uničijo? Bog daj, da bi bili zadovoljni in prebivali na drugi strani Jordana!',
        8: 'Oh Gospod, kaj naj rečem, ko Izrael obrača svoje hrbte pred svojimi sovražniki!',
        9: 'Kajti Kánaanci in vsi prebivalci dežele bodo slišali o tem in nas bodo obkrožili naokoli in naše ime iztrebili z zemlje in kaj boš storil svojemu velikemu imenu?«',
        10: 'Gospod je rekel Józuetu: »Dvigni se, zakaj tako ležiš na svojem obrazu?',
        11: 'Izrael je grešil in prav tako so prekršili mojo zavezo, ki sem jim jo zapovedal, kajti vzeli so si celó od preklete stvari in tudi kradli in tudi prikrivali so in to so si postavili celó med svoje stvari.',
        12: 'Zato Izraelovi otroci niso mogli obstati pred svojimi sovražniki, temveč so obrnili svoje hrbte pred svojimi sovražniki, ker so bili prekleti. Niti jaz ne bom več z vami, razen če ne uničite prekletega izmed vas.',
        13: 'Vstani, posvéti ljudstvo in reci: ›Posvetite se za jutrišnji dan,‹ kajti tako govori Gospod, Izraelov Bog: ›V vaši sredi je prekleta stvar, oh Izrael. Ne moreš stati pred svojimi sovražniki, dokler izmed sebe ne odstranite preklete stvari.',
        14: 'Zato boste zjutraj privedeni glede na svoje rodove. In zgodilo se bo, da bo rod, ki ga Gospod vzame, prišel glede na njegove družine, in družina, ki jo bo Gospod vzel, bo prišla po svojih gospodinjstvih, in gospodinjstvo, ki ga bo Gospod vzel, bo prišlo mož za možem.',
        15: 'Zgodilo se bo, da kdor je vzet s prekleto stvarjo, bo sežgan z ognjem, on in vse, kar ima, ker je prekršil Gospodovo zavezo in ker je izvršil neumnost v Izraelu.‹«',
        16: 'Tako je Józue zgodaj zjutraj vstal in Izraela privedel po njihovih rodovih in izbran je bil Judov rod.',
        17: 'Privedel je Judovo družino in izbrana je bila Zerahova družina. Privedel je družino Zerahovcev, moškega za moškim in izbran je bil Zabdí.',
        18: 'Privedel je njegovo gospodinjstvo, moškega za moškim in izbran je bil Ahán, sin Karmíja, sin Zabdíja, sin Zeraha, iz Judovega rodu.',
        19: 'Józue je rekel Ahánu: »Moj sin, izkaži, prosim te, slavo Gospodu, Izraelovemu Bogu in mu naredi priznanje in povej mi torej, kaj si storil. Tega ne skrivaj pred menoj.«',
        20: 'Ahán je odgovoril Józuetu in rekel: »Zares, grešil sem zoper Gospoda, Izraelovega Boga in tako in tako sem storil.',
        21: 'Ko sem med pleni zagledal lepo babilonsko obleko in dvesto šeklov srebra in klin iz zlata, težak petdeset šeklov, potem sem zahlepel [po] njih in jih vzel. Glej, skriti so v zemlji, v sredi mojega šotora in srebro pod tem.«',
        22: 'Tako je Józue poslal poslanca in stekla sta v šotor in glej, to je bilo skrito v njegovem šotoru in srebro pod tem.',
        23: 'Vzeli so jih iz srede šotora in jih prinesli k Józuetu in k vsem Izraelovim otrokom in jih položili pred Gospoda.',
        24: 'Józue in ves Izrael z njim, je vzel Zerahovega sina Ahána, srebro, obleko, klin iz zlata, njegove sinove, njegove hčere, njegove vole, njegove osle, njegove ovce, njegov šotor in vse, kar je imel in odvedli so jih v dolino Ahór.',
        25: 'Józue je rekel: »Zakaj si nas spravil v težave? Gospod te bo ta dan spravil v težave.« In ves Izrael ga je kamnal s kamni in jih sežgal z ognjem, potem ko so jih kamnali s kamni.',
        26: 'Nad njim so dvignili velik kup kamenja do tega dne. Tako se je Gospod obrnil od okrutnosti svoje jeze. Zato je bilo ime tega kraja imenovano Dolina Ahór do tega dne.',
    },
    8: {
        1: 'Gospod je rekel Józuetu: »Ne boj se niti ne bodi zaprepaden. S seboj vzemi vse bojno ljudstvo in se dvigni, pojdi gor do Aja. Glej, v tvojo roko sem izročil ajskega kralja, njegovo ljudstvo, njegovo mesto in njegovo deželo.',
        2: 'Aju in njegovemu kralju boš storil, kakor si storil Jerihi in njenemu kralju. Samo njegov plen in njegovo živino si boste zaplenili. Zadaj za mestom si postavi zasedo.«',
        3: 'Tako je Józue vstal in vse bojno ljudstvo, da gredo gor zoper Aj. Józue je izbral trideset tisoč močnih junaških mož in jih ponoči odposlal.',
        4: 'Zapovedal jim je, rekoč: »Glejte, prežali boste v zasedi zoper mesto, torej za mestom. Ne pojdite zelo daleč od mesta, temveč vsi bodite pripravljeni.',
        5: 'Jaz in vse ljudstvo, ki je z menoj, se bomo približali mestu in zgodilo se bo, ko bodo prišli ven zoper nas, kakor prvič, da bomo pobegnili pred njimi,',
        6: '(kajti prišli bodo ven za nami), dokler jih ne bomo pritegnili iz mesta, kajti rekli bodo: ›Pred nami bežijo, kakor prvič.‹ Zato bomo pobegnili pred njimi.',
        7: 'Potem boste vstali iz zasede in se polastili mesta, kajti Gospod, vaš Bog, ga bo izročil v vašo roko.',
        8: 'Zgodilo se bo, ko boste zavzeli mesto, da boste požgali mesto. Glede na Gospodovo zapoved boste storili. Poglejte, zapovedal sem vam.«',
        9: 'Józue jih je torej poslal naprej in odšli so, da ležijo v zasedi in ostanejo med Betelom in Ajem, na zahodni strani Aja. Toda Józue je to noč prenočil med ljudstvom.',
        10: 'Józue je vstal zgodaj zjutraj, preštel ljudstvo in odšel gor, on in Izraelovi starešine, pred ljudstvo Aja.',
        11: 'Vse ljudstvo, celo bojno ljudstvo, ki je bilo z njim, je odšlo gor, se približalo, prišlo pred mesto in se utaborilo na severni strani Aja. Torej tam je bila dolina med njimi in Ajem.',
        12: 'Vzel je okoli pet tisoč mož in jih postavil, da ležijo v zasedi med Betelom in Ajem, na zahodni strani mesta.',
        13: 'Ko so postavili ljudstvo, torej vso vojsko, ki je bila na severu mesta in svoje prežavce v zasedi na zahodni strani mesta, je to noč Józue odšel v sredo doline.',
        14: 'Ko je kralj Aja to videl, se je pripetilo, da so pohiteli in zgodaj vstali in možje iz mesta so odšli ven zoper Izraela, da se bojujejo, on in vse njegovo ljudstvo, ob določenem času pred ravnino. Toda ni vedel, da so bili za mestom zoper njega prežavci v zasedi.',
        15: 'Józue in ves Izrael so se pretvarjali kakor bi bili poraženi pred njimi in pobegnili po poti divjine.',
        16: 'Vse ljudstvo, ki je bilo v Aju, je bilo sklicano skupaj, da jih zasledujejo. Zasledovali so Józueta in bili so pritegnjeni proč iz mesta.',
        17: 'V Aju ali v Betelu ni ostal niti mož, ki ne bi odšel ven za Izraelom in mesto so pustili odprto in sledili za Izraelom.',
        18: 'Gospod je rekel Józuetu: »Iztegni sulico, ki je v tvoji roki, zoper Aj, kajti jaz ga bom dal v tvojo roko.« Józue je zoper mesto iztegnil sulico, ki jo je imel v svoji roki.',
        19: 'Zaseda je hitro vstala iz svojega kraja in stekli so takoj, ko je iztegnil svojo roko. Vstopili so v mesto, ga zavzeli, pohiteli in mesto zažgali.',
        20: 'Ko so možje iz Aja pogledali za seboj, so videli in glej, dim iz mesta se je dvigoval proti nebu in niso imeli moči, da pobegnejo to pot ali tisto pot. Ljudstvo, ki je bežalo k divjini, se je obrnilo nazaj proti zasledovalcem.',
        21: 'Ko je Józue in ves Izrael videl, da je zaseda zavzela mesto in da se iz mesta dviguje dim, potem so se ponovno obrnili in usmrtili može iz Aja.',
        22: 'In drugi so izšli iz mesta zoper njih. Tako so bili v sredi Izraela, nekateri na tej strani in nekateri na oni strani in udarili so jih tako, da nobenega izmed njih niso pustili ostati ali pobegniti.',
        23: 'Kralja Aja so prijeli živega in ga privedli pred Józueta.',
        24: 'Ko je Izrael naredil konec pobijanju vseh prebivalcev Aja na polju, v divjini, kjer so jih zasledovali in ko so vsi padli pod ostrino meča, dokler niso bili použiti, se je pripetilo, da so se vsi Izraelci vrnili v Aj in ga udarili z ostrino meča.',
        25: 'Bilo je tako, da je bilo vseh, ki so ta dan padli, tako mož in žensk, dvanajst tisoč, torej vsi možje iz Aja.',
        26: 'Kajti Józue svoje roke, s katero je iztegnil sulico, ni potegnil nazaj, dokler ni popolnoma uničil vseh prebivalcev Aja.',
        27: 'Samo živino in ukradeno blago iz mesta si je Izrael vzel za plen, glede na Gospodovo besedo, ki jo je zapovedal Józuetu.',
        28: 'Józue je požgal Aj in ga naredil kup na veke, opustošenje do današnjega dne.',
        29: 'Ajskega kralja je obesil na drevo do večera in takoj, ko je sonce zašlo, je Józue zapovedal, da njegovo truplo vzamejo dol iz drevesa in ga odvržejo pri vhodu velikih vrat mesta in nad njim naložijo velik kup kamenja, ki ostaja do tega dne.',
        30: 'Potem je Józue zgradil oltar Gospodu, Izraelovemu Bogu, na gori Ebál,',
        31: 'kakor je Gospodov služabnik Mojzes zapovedal Izraelovim otrokom, kakor je to zapisano v knjigi Mojzesove postave, oltar iz celih kamnov, nad katere noben človek ni dvignil nobenega železa in na njem so darovali žgalne daritve Gospodu in žrtvovali mirovne daritve.',
        32: 'Na kamne je napisal prepis iz Mojzesove postave, ki jo je napisal v prisotnosti Izraelovih otrok.',
        33: 'Ves Izrael, njihove starešine, častniki in njihovi sodniki, so stali na tej strani skrinje in na oni strani, pred duhovniki Lévijevci, ki so nosili skrinjo Gospodove zaveze, kakor tudi tujec, kakor ta, ki je bil rojen med njimi. Polovica izmed njih nasproti gore Garizím in polovica izmed njih nasproti gore Ebál, kakor je Gospodov služabnik Mojzes prej zapovedal, da bodo blagoslovili izraelsko ljudstvo.',
        34: 'Potem je bral vse besede iz postave, blagoslove in prekletstva, glede na vse, kar je zapisano v knjigi postave.',
        35: 'Ni bilo besede od vsega, kar je Mojzes zapovedal, česar Józue ni prebral pred vso Izraelovo skupnostjo, z ženskami, malčki in tujci, ki so bili seznanjeni med njimi.',
    },
    9: {
        1: 'Pripetilo se je, ko so vsi kralji, ki so bili na tej strani Jordana, na hribih, v dolinah in po vseh pokrajinah vélikega morja nasproti Libanonu, Hetejci, Amoréjci, Kánaanci, Perizéjci, Hivéjci in Jebusejci, slišali o tem,',
        2: 'da so se zbrali skupaj, da se soglasno bojujejo z Józuetom in z Izraelom.',
        3: 'Ko so prebivalci Gibeóna slišali, kaj je Józue storil Jerihi in Aju,',
        4: 'so prebrisano storili in odšli ter se naredili kakor, da so bili predstavniki in na svoje osle dali stare vreče in vinske mehove, stare in raztrgane ter jih povezali',
        5: 'in stare čevlje, zakrpane na njihovih stopalih in stare obleke na njih in ves kruh njihove popotnice je bil suh in drobljiv.',
        6: 'Odšli so k Józuetu v tabor pri Gilgálu, in rekli njemu in Izraelovim možem: »Prišli smo iz daljne dežele, zdaj torej sklenite zavezo z nami.«',
        7: 'Možje iz Izraela so rekli Hivéjcem: »Morda prebivate med nami in kako naj sklenemo zavezo z vami?«',
        8: 'Ti so Józuetu rekli: »Mi smo tvoji služabniki.« Józue jim je rekel: »Kdo ste? In od kod ste prišli?«',
        9: 'Rekli so mu: »Iz zelo oddaljene dežele so prišli tvoji služabniki zaradi imena Gospoda, tvojega Boga, kajti slišali smo sloves o njem in vse, kar je storil v Egiptu',
        10: 'in vse, kar je storil dvema kraljema Amoréjcev, ki sta bila onkraj Jordana, hešbónskemu kralju Sihónu in bašánskemu kralju Ogu, ki je bil pri Aštarótu.',
        11: 'Zato so nam naši starešine in vsi prebivalci dežele govorili, rekoč: ›S seboj vzemite živež za potovanje in pojdite, da jih srečate in jim recite: ›Mi smo vaši služabniki, zato zdaj sklenite zavezo z nami.‹‹',
        12: 'Ta naš kruh smo vzeli še vročega za našo popotnico iz naših hiš na dan, ko smo šli, da gremo k vam, toda sedaj, glejte, je ta suh in drobljiv.',
        13: 'Ti vinski mehovi, ki smo jih napolnili, so bili novi, in glejte, raztrgani so. Te naše obleke in naši čevlji so postali stari zaradi razloga zelo dolgega potovanja.«',
        14: 'Možje so vzeli od njihovega živeža, niso pa vprašali za nasvet pri Gospodovih ustih.',
        15: 'Józue je z njimi sklenil mir in z njimi sklenil zavezo, da jih pusti žive, in princi skupnosti so jim prisegli.',
        16: 'Pripetilo pa se je ob koncu treh dni, potem ko so z njimi sklenili zavezo, da so slišali, da so bili njihovi sosedje in da so prebivali med njimi.',
        17: 'Izraelovi otroci so odpotovali in na tretji dan prišli v njihova mesta. Torej njihova mesta so bila Gibeón, Kefíra, Beerót in Kirját Jearím.',
        18: 'Izraelovi otroci jih niso udarili, ker so jim princi skupnosti prisegli pri Gospodu, Izraelovemu Bogu. In vsa skupnost je godrnjala zoper prince.',
        19: 'Toda vsi princi so vsej skupnosti rekli: »Prisegli smo jim pri Gospodu, Izraelovem Bogu. Sedaj se jih torej ne smemo dotakniti.',
        20: 'To jim bomo storili. Celo žive jih bomo pustili, da ne bi bil nad nami bes zaradi prisege, ki smo jim jo prisegli.«',
        21: 'Princi so jim rekli: »Naj živijo, toda naj bodo drvarji in prinašalci vode vsej skupnosti,« kakor so jim princi obljubili.',
        22: 'Józue jih je dal poklicati in jim spregovoril, rekoč: »Zakaj ste nas preslepili, rekoč: ›Mi smo zelo daleč od vas,‹ ko prebivate med nami?',
        23: 'Zdaj ste torej prekleti in nihče izmed vas naj ne bo prost pred tem, da bi bili sužnji, drvarji in prinašalci vode za hišo mojega Boga.«',
        24: 'Józuetu so odgovorili in rekli: »Ker je bilo tvojim služabnikom zagotovo povedano to, kako je Gospod, tvoj Bog, zapovedal svojemu služabniku Mojzesu, da vam da vso deželo in da pred seboj uničite vse prebivalce dežele, zato smo bili zaradi vas boleče prestrašeni za svoja življenja in smo storili to stvar.',
        25: 'In sedaj glej, mi smo v tvoji roki. Kakor se ti zdi dobro in pravilno, da nam storiš, stôri.«',
        26: 'Tako jim je storil in jih osvobodil iz roke Izraelovih otrok, da jih niso pobili.',
        27: 'Józue jih je ta dan naredil za drvarje in prinašalce vode za skupnost in za Gospodov oltar, celo do tega dne, na kraju, ki bi ga izbral.',
    },
    10: {
        1: 'Pripetilo se je torej, ko je jeruzalemski kralj Adoní Cedek slišal, kako je Józue zavzel Aj in ga popolnoma uničil; kakor je storil Jerihi in njenemu kralju, tako je storil Aju in njegovemu kralju; in kako so prebivalci Gibeóna sklenili mir z Izraelom in so bili med njimi;',
        2: 'da so se silno bali, ker je bil Gibeón veliko mesto, kakor eno izmed kraljevskih mest in ker je bil večji kakor Aj in vsi njihovi možje so bili mogočni.',
        3: 'Zato je jeruzalemski kralj Adoní Cedek poslal k Hohámu, kralju v Hebrónu in Pirámu, kralju v Jarmútu in Jafíju, kralju v Lahíšu in Debírju, kralju v Eglónu, rekoč:',
        4: '»Pridite gor k meni in mi pomagajte, da bomo lahko udarili Gibeón, kajti ta je sklenil mir z Józuetom in z Izraelovimi otroki.«',
        5: 'Zato se je pet kraljev izmed Amoréjcev, kralj iz Jeruzalema, kralj iz Hebróna, kralj iz Jarmúta, kralj iz Lahíša in kralj iz Eglóna, zbralo skupaj in odšlo gor, oni in vse njihove vojske in se utaborili pred Gibeónom in začeli vojno zoper njega.',
        6: 'Možje iz Gibeóna so poslali k Józuetu, v tabor pri Gilgálu, rekoč: »Ne odtegni svoje roke od svojih služabnikov. Hitro pridi gor k nam in nas reši in nam pomagaj, kajti vsi kralji Amoréjcev, ki prebivajo po gorah, so skupaj zbrani zoper nas.«',
        7: 'Tako se je Józue vzpel iz Gilgála, on in vse bojno ljudstvo z njim in vsi močni junaški možje.',
        8: 'Gospod je rekel Józuetu: »Ne boj se jih, kajti izročil sem jih v tvojo roko. Niti mož izmed njih ne bo obstal pred teboj.«',
        9: 'Józue je torej nenadoma prišel k njim in vso noč so hodili gor od Gilgála.',
        10: 'Gospod jih je porazil pred Izraelom ter jih pri Gibeónu usmrtil z velikim pobojem in jih zasledoval na poti, ki gre gor do Bet Horóna in jih udarjal do Azéke in proti Makédi.',
        11: 'Ko so bežali izpred Izraela in so bili pri spuščanju dol k Bet Horónu, se je pripetilo, da je Gospod z neba nanje metal velike kamne do Azéke in so umrli. Bilo jih je več, ki so umrli od kamnite toče, kakor tistih, ki so jih Izraelovi otroci usmrtili z mečem.',
        12: 'Potem je Józue spregovoril Gospodu na dan, ko je pred Izraelovimi otroki Gospod izročil Amoréjce in rekel pred očmi Izraela: »Sonce, ti stoj mirno nad Gibeónom in ti luna v dolini Ajalón.«',
        13: 'Sonce je stalo mirno in luna je obstala, dokler se ljudstvo ni maščevalo nad svojimi sovražniki. Mar ni to zapisano v Jasherjevi knjigi? Tako je sonce mirno stalo na sredi neba in približno cel dan ni pohitelo, da bi zašlo.',
        14: 'Pred tem niti za tem ni bilo takšnega dne, da bi Gospod prisluhnil glasu moža, kajti Gospod se je bojeval za Izrael.',
        15: 'Józue se je vrnil in ves Izrael z njim, k taboru pri Gilgálu.',
        16: 'Toda teh pet kraljev je pobegnilo in se skrilo v votlini pri Makédi.',
        17: 'To je bilo povedano Józuetu, rekoč: »Pet kraljev je najdenih skritih v votlini pri Makédi.«',
        18: 'Józue je rekel: »Na odprtino votline zavalite velike kamne in poleg postavite može, da jih varujejo.',
        19: 'Ne stojte, temveč sledite za svojimi sovražniki in udarite najbolj zadnje izmed njih. Ne trpite, da vstopijo v svoja mesta, kajti Gospod, vaš Bog, jih je izročil v vašo roko.«',
        20: 'Pripetilo se je, ko so Józue in Izraelovi otroci z zelo velikim pokolom, dokler niso bili použiti, naredili konec njihovemu pobijanju, da je preostanek, ki je preostal izmed njih, vstopil v utrjena mesta.',
        21: 'In vse ljudstvo se je v miru vrnilo k taboru, k Józuetu, pri Makédi. Nihče ni svojega jezika premaknil zoper kateregakoli izmed Izraelovih otrok.',
        22: 'Potem je Józue rekel: »Odprite odprtino votline in teh pet kraljev privedite k meni, ven iz votline.«',
        23: 'Storili so tako in iz votline so k njemu privedli teh pet kraljev, kralja iz Jeruzalema, kralja iz Hebróna, kralja iz Jarmúta, kralja iz Lahíša in kralja iz Eglóna.',
        24: 'Ko so te kralje privedli k Józuetu, se je pripetilo, da je Józue dal poklicati vse Izraelove može in rekel poveljnikom bojevnikov, ki so odšli z njim: »Pridite bliže, položite svoja stopala na vratove teh kraljev.« Približali so se in svoja stopala položili na njihove vratove.',
        25: 'Józue jim je rekel: »Ne bojte se niti ne bodite zaprepadeni, bodite močni in odločnega poguma, kajti tako bo Gospod storil vsem vašim sovražnikom, zoper katere se borite.«',
        26: 'Potem jih je Józue udaril, jih usmrtil in jih obesil na pet dreves; in do večera so viseli na drevesih.',
        27: 'Ob času zahajanja sonca pa se je pripetilo, da je Józue zapovedal in so jih sneli iz dreves in jih vrgli v votlino, v kateri so bili skriti in na ustje votline so položili velike kamne, ki ostajajo do točno tega dne.',
        28: 'Ta dan je Józue zavzel Makédo in jo udaril z ostrino meča in njenega kralja je popolnoma uničil, njih in vse duše, ki so bile tam. Nikogar ni pustil ostati. Kralju v Makédi pa je storil, kakor je storil kralju v Jerihi.',
        29: 'Potem je Józue in ves Izrael z njim, prešel od Makéde v Libno in se boril zoper Libno.',
        30: 'Tudi njo je Gospod izročil in njenega kralja, v Izraelovo roko. Udaril jo je z ostrino meča in vse duše, ki so bile v njej. Nikogar ni pustil preostati v njej, toda njenemu kralju je storil, kakor je storil kralju Jerihe.',
        31: 'Józue in ves Izrael z njim, je prešel od Libne do Lahíša in se utaboril zoper njega in se boril zoper njega.',
        32: 'Gospod je Lahíš izročil v Izraelovo roko, ki so ga zavzeli na drugi dan in ga udaril z ostrino meča in vse duše, ki so bile tam, glede na vse, kar je storil Libni.',
        33: 'Potem je prišel gor Horám, kralj v Gezerju, da pomaga Lahíšu, in Józue je udaril njega in njegovo ljudstvo, dokler nikogar ni pustil preostati.',
        34: 'Iz Lahíša je Józue prešel do Eglóna in ves Izrael z njim in utaborili so se zoper njega in se borili zoper njega.',
        35: 'Zavzeli so ga na ta dan in ga udarili z ostrino meča in vse duše, ki so bile tam, je ta dan popolnoma uničil, glede na vse, kar je storil Lahíšu.',
        36: 'Józue in ves Izrael z njim, je odšel gor od Eglóna, do Hebróna in so se borili zoper njega,',
        37: 'ga zavzeli in udarili z ostrino meča in njihovega kralja in vsa njihova mesta in vse duše, ki so bile v njem. Nikogar ni pustil preostati, glede na vse, kar je storil Eglónu, temveč ga je popolnoma uničil in vse duše, ki so bile v njem.',
        38: 'Józue se je vrnil in ves Izrael z njim, do Debírja in se boril zoper njega',
        39: 'in ga zavzel in njegovega kralja in vsa njegova mesta. Udarili so jih z ostrino meča in popolnoma uničili vse duše, ki so bile v njem. Nikogar ni pustil preostati. Kakor je storil Hebrónu, tako je storil Debírju in njegovemu kralju, kakor je storil tudi Libni in njenemu kralju.',
        40: 'Tako je Józue udaril vso hribovito deželo, južno [deželo], [deželo] dolin, izvirov in vse njihove kralje. Ničesar ni pustil preostati, temveč je popolnoma uničil vse, kar je dihalo, kakor je zapovedal Gospod, Izraelov Bog.',
        41: 'Józue jih je udarjal od Kadeš Barnée, celo do Gaze in vso Gošensko pokrajino, celo do Gibeóna.',
        42: 'Vse te kralje in njihove dežele je Józue zavzel naenkrat, ker se je Gospod, Izraelov Bog, boril za Izrael.',
        43: 'In Józue se je vrnil in ves Izrael z njim, v tabor h Gilgálu.',
    },
    11: {
        1: 'Pripetilo se je, ko je Jabín, kralj iz Hacórja, slišal te stvari, da je poslal k Jobábu, kralju Madóna in h kralju Šimróna in h kralju Ahšáfa',
        2: 'in h kraljem, ki so bili na severu gora in na ravninah južno od Kinérota in v dolino in na meje Dora na zahodu',
        3: 'in h Kánaancem na vzhodu in na zahodu in k Amoréjcem in k Hetejcem in k Perizéjcem in k Jebusejcem po gorah in k Hivéjcem pod Hermonom v deželi Micpa.',
        4: 'In odšli so ven, oni in vse njihove vojske z njimi, mnogo ljudstva, po številu celo kakor peska, ki je na morski obali, s konji in zelo mnogimi bojnimi vozovi.',
        5: 'Ko so se vsi ti kralji srečali skupaj, so prišli in se skupaj utaborili pri vodah Meróma, da se borijo zoper Izrael.',
        6: 'Gospod je rekel Józuetu: »Ne bodi prestrašen zaradi njih, kajti jutri ob tem času jih bom vse umorjene izročil pred Izraela. Njihovim konjem boš prerezal Ahilove tetive in njihove bojne vozove sežgal z ognjem.«',
        7: 'Tako je zoper njih nenadoma prišel Józue in vse bojno ljudstvo z njim pri vodah Meróa in padli so nanje.',
        8: 'Gospod jih je izročil v roko Izraela, ki jih je udaril in pregnal do vélikega Sidóna in do Misrefót Majima in vzhodno k dolini Micpe in udarjali so jih, dokler niso pustili nikogar preostati.',
        9: 'Józue jim je storil, kakor mu je Gospod zaukazal. Njihovim konjem je prerezal Ahilove tetive in njihove bojne vozove zažgal z ognjem.',
        10: 'Józue se je ob tistem času obrnil nazaj in zavzel Hacór in njihovega kralja udaril z mečem, kajti Hacór je bil prej poglavar vseh tistih kraljestev.',
        11: 'Vse duše, ki so bile v njem, so udarili z ostrino meča; popolnoma so jih uničili, tam ni ostal nihče, da diha. In Hacór je požgal z ognjem.',
        12: 'Vsa mesta tistih kraljev in vse kralje izmed njih je Józue zajel in jih udaril z ostrino meča in jih popolnoma uničil, kakor je zapovedal Gospodov služabnik Mojzes.',
        13: 'Toda kar se tiče mest, ki so mirovala v svoji moči, pa Izrael ni požgal nobenega izmed njih, razen samo Hacór; ki ga je požgal Józue.',
        14: 'Ves plen teh mest in živino so si Izraelovi otroci vzeli za plen, toda vsakega človeka so udarili z ostrino meča, dokler jih niso uničili niti niso pustili nobenega da diha.',
        15: 'Kakor je Gospod zapovedal svojemu služabniku Mojzesu, tako je Mojzes zapovedal Józuetu in tako je storil Józue. Ničesar ni pustil nenarejenega, od vsega, kar je Gospod zapovedal Mojzesu.',
        16: 'Tako je Józue zavzel vso tisto deželo, hribe in vso južno deželo, vso deželo Gošen, dolino in ravnino, Izraelovo goro in dolino te iste,',
        17: 'torej od gore Halak, ki gre gor k Seírju, celo do Báal Gada v libanonski dolini pod goro Hermon. Zajel je vse njihove kralje, jih udaril in usmrtil.',
        18: 'Józue je dolgo časa bojeval vojno z vsemi tistimi kralji.',
        19: 'Tam ni bilo mesta, ki bi z Izraelovimi otroki sklenilo mir, razen Hivéjcev, prebivalcev Gibeóna. Vse druge so zavzeli v bitki.',
        20: 'Kajti to je bilo od Gospoda, da zakrkne njihova srca, da bi prišli v boj zoper Izrael, da bi jih lahko popolnoma uničil in da ne bi imeli naklonjenosti, temveč da bi jih lahko uničil, kakor je Gospod zapovedal Mojzesu.',
        21: 'Ob tistem času je prišel Józue in iztrebil Anákovce z gora, iz Hebróna, iz Debírja, iz Anába, iz vseh Judovih gora in iz vseh Izraelovih gora. Józue jih je popolnoma uničil z njihovimi mesti.',
        22: 'Nobeden izmed Anákovcev ni ostal v deželi Izraelovih otrok. Ostali so samo v Gazi, Gatu in v Ašdódu.',
        23: 'Tako je Józue zavzel celotno deželo, glede na vse, kar je Gospod rekel Mojzesu, in Józue jo je dal za dediščino Izraelu, glede na njihove oddelke po njihovih rodovih. In dežela je počivala pred vojno.',
    },
    12: {
        1: 'Torej to so kralji dežele, ki so jo Izraelovi otroci udarili in njihovo deželo vzeli v last na drugi strani Jordana, proti sončnemu vzhodu, od reke Arnón, do gore Hermon in vso ravnino na vzhodu:',
        2: 'amoréjski kralj Sihón, ki je prebival v Hešbónu in vladal od Aroêrja, ki je na bregu reke Arnón in od sredine reke in od polovice Gileáda, celo do reke Jabók, kar je meja Amónovih otrok;',
        3: 'in od ravnine do Kinérotskega morja na vzhodu in do ravninskega morja, torej slanega morja na vzhodu, pot do Bet Ješimóta in od juga pod Ašdód-Pisgo.',
        4: '§ Pokrajina bašánskega kralja Oga, ki je bila od preostanka velikanov, ki so prebivali pri Aštarótu in pri Edréi',
        5: 'in je kraljeval na gori Hermon, v Salhi in po vsem Bašánu, do meje Gešuréjcev in Maahčánov in polovice Gileáda, meje Sihóna, kralja v Hešbónu.',
        6: 'Te so udarili Gospodov služabnik Mojzes in Izraelovi otroci. Gospodov služabnik Mojzes jo je dal v posest Rubenovcem in Gádovcem in polovici Manásejevega rodu.',
        7: 'Ti so kralji dežele, ki so jo Józue in Izraelovi otroci udarili na tej strani Jordana na zahodu, od Báal Gada, v dolini Libanon, celo do gore Halak, ki gre gor k Seírju, ki jo je Józue izročil Izraelovim rodovom za posest, glede na njihove oddelke;',
        8: 'po gorah, po dolinah, po ravninah, po izvirih, po divjini in po južni deželi: Hetejce, Amoréjce in Kánaance, Perizéjce, Hivéjce in Jebusejce.',
        9: 'Kralj Jerihe, eden; kralj Aja, ki je poleg Betela, eden;',
        10: 'kralj Jeruzalema, eden; kralj Hebróna, eden;',
        11: 'kralj Jarmúta, eden; kralj Lahíša, eden;',
        12: 'kralj Eglóna, eden; kralj Gezerja, eden;',
        13: 'kralj Debírja, eden; kralj Gederja, eden;',
        14: 'kralj Horme, eden; kralj Aráda, eden;',
        15: 'kralj Libne, eden; kralj Aduláma, eden;',
        16: 'kralj Makéde, eden; kralj Betela, eden;',
        17: 'kralj Tapúaha, eden; kralj Heferja, eden;',
        18: 'kralj Aféka, eden; kralj Lašaróna, eden;',
        19: 'kralj Madóna, eden; kralj Hacórja, eden;',
        20: 'kralj Šimrón Meróna, eden; kralj Ahšáfe, eden;',
        21: 'kralj Taanáha, eden; kralj Megíde, eden;',
        22: 'kralj Kedeša, eden; kralj Jokneáma pri Karmelu, eden;',
        23: 'kralj Dora na Dorovi pokrajini, eden; kralj narodov Gilgála, eden;',
        24: 'kralj Tirce, eden; vseh kraljev enaintrideset.',
    },
    13: {
        1: 'Torej Józue je bil star in zvrhan v letih in Gospod mu je rekel: »Star si in zvrhan v letih in tam ostaja še zelo veliko dežele, da bi bila posedena.',
        2: 'To je dežela, ki je še ostala: vse meje Filistejcev in ves Gešur,',
        3: 'od Šihórja, ki je pred Egiptom, celo do mej severno od Ekróna, ki je štet h Kánaancem; pet filistejskih knezov: Gazejci, Ašdódci, Aškelónci, Gitéjci in Ekrónci; tudi Avéjci;',
        4: 'od juga, vsa dežela Kánaancev in Mara, ki je poleg Sidóncev, do Aféka, do meja Amoréjcev',
        5: 'in dežela Gebálcev in ves Libanon proti sončnemu vzhodu, od Báal Gada pod goro Hermon do vstopa v Hamát.',
        6: 'Vse prebivalce hribovite dežele, od Libanona do Misrefót Majima in vse Sidónce bom jaz napodil izpred Izraelovih otrok. Samo razdeli jo z žrebom Izraelcem v dediščino, kakor sem ti zapovedal.',
        7: 'Zdaj torej razdeli to deželo za dediščino vsem devetim rodovom in polovici Manásejevega rodu,',
        8: 's katerimi so Rubenovci in Gádovci prejeli svojo dediščino, ki jim jo je dal Mojzes, onkraj Jordana proti vzhodu, torej kakor jim je dal Gospodov služabnik Mojzes:',
        9: 'od Aroêrja, ki je na bregu reke Arnón in mesta, ki je na sredi reke in vso ravnino Médebo do Dibóna;',
        10: 'in vsa mesta amoréjskega kralja Sihóna, ki je kraljeval v Hešbónu, do meje Amónovih otrok;',
        11: 'Gileád in mejo Gešuréjcev in Maahčánov in vse gore Hermona in ves Bašán, do Salhe;',
        12: '§ vse Ogovo kraljestvo v Bašánu, ki je kraljeval v Aštarótu in v Edréi, ki je ostalo od preostanka velikanov, kajti te je Mojzes udaril in jih vrgel ven.«',
        13: 'Kljub temu Izraelovi otroci niso pregnali Gešuréjcev niti Maahčánov, temveč Gešuréjci in Maahčáni prebivajo med Izraelci do tega dne.',
        14: 'Samo Lévijevemu rodu ni dal nobene dediščine. Daritve Gospoda, Izraelovega Boga, narejene z ognjem, so njihova dediščina, kakor jim je rekel.',
        15: 'Mojzes je dal rodu Rubenovih otrok dediščino glede na njihove družine.',
        16: 'Njihova pokrajina je bila od Aroêrja, ki je na bregu reke Arnón in mesto, ki je na sredi reke in vsa ravnina pri Médebi;',
        17: 'Hešbón in vsa njegova mesta, ki so na ravnini; Dibón in Bamót Báal in Bet Báal Meón,',
        18: 'Jahac, Kedemót, Mefáat,',
        19: 'Kirjatájim, Sibmo in Ceret Šahar na gori doline,',
        20: 'Bet Peór, Ašdód-Pisgo, Bet Ješimót',
        21: 'in vsa mesta ravnine in vse kraljestvo amoréjskega kralja Sihóna, ki je kraljeval v Hešbónu, ki ga je Mojzes udaril z midjánskimi princi Evíjem, Rekemom, Curjem, Hurom in Rebom, ki so bili sihónski vojvode, prebivajoči v deželi.',
        22: 'Tudi Beórjevega sina Bileáma, napovedovalca usode, so Izraelovi otroci ubili z mečem med tistimi, ki so jih umorili.',
        23: 'Meja Rubenovih otrok je bil Jordan in njegova meja. To je bila dediščina Rubenovih otrok po njihovih družinah, mestih in njihovih vaseh.',
        24: 'Mojzes je dediščino izročil Gadovemu rodu, torej Gadovim otrokom, glede na njihove družine.',
        25: 'Njihova pokrajina je bila Jazêr in vsa mesta Gileáda in polovica dežele Amónovih otrok, do Aroêrja, ki je pred Rabo;',
        26: 'in od Hešbóna do Ramát Micpéja in Betoníma in od Mahanájima do meje Debírja;',
        27: 'v dolini pa Beth–aram, Bet Nimra, Sukót in Cafón, preostanek kraljestva hešbónskega kralja Sihóna, Jordan in njegova meja, celó do roba Kinéretskega morja na drugi strani Jordana proti vzhodu.',
        28: 'To je dediščina Gadovih otrok po njihovih družinah, mestih in njihovih vaseh.',
        29: 'Mojzes je dal dediščino polovici Manásejevega rodu. To je bila posest polovice rodu Manásejevih otrok po njihovih družinah.',
        30: 'Njihovo ozemlje je bilo od Mahanájima, ves Bašán, celotno kraljestvo bašánskega kralja Oga in vsa Jaírova mesta, ki so v Bašánu, šestdeset mest.',
        31: 'Polovica Gileáda, Aštarót in Edréi, mesta Ogovega kraljestva v Bašánu, so pripadla otrokom Mahírja, Manásejevega sina, celo do polovice Mahírjevih otrok po njihovih družinah.',
        32: 'To so dežele, ki jih je Mojzes razdelil v dediščino na moábskih planjavah, na drugi strani Jordana, pri Jerihi, proti vzhodu.',
        33: 'Toda Lévijevemu rodu Mojzes ni dal nobene dediščine. Gospod, Izraelov Bog, je bil njihova dediščina, kakor jim je rekel.',
    },
    14: {
        1: 'To so dežele, ki so jih Izraelovi otroci podedovali v kánaanski deželi, ki so jim jo duhovnik Eleazar, Nunov sin Józue in poglavarji očetov rodov Izraelovih otrok razdelili v dediščino.',
        2: 'Njihova dediščina je bila po žrebu, kakor je Gospod zapovedal po Mojzesovi roki, za devet rodov in za polovico rodu.',
        3: 'Kajti Mojzes je na drugi strani Jordana dal dediščino dvema rodovoma in polovici rodu, toda Lévijevcem med njimi ni dal nobene dediščine.',
        4: 'Kajti od Jožefovih otrok sta bila dva rodova, Manáse in Efrájim. Zato v deželi niso dali nobenega deleža Lévijevcem, razen mest, da prebivajo v njih, z njihovimi predmestji za njihovo živino in za njihovo imetje.',
        5: 'Kakor je Gospod zapovedal Mojzesu, tako so Izraelovi otroci storili in razdelili so deželo.',
        6: 'Potem so Judovi otroci prišli k Józuetu v Gilgál in Jefunéjev sin Kaléb, Kenázovec, mu je rekel: »Ti poznaš stvar, ki jo je Gospod rekel Božjemu možu Mojzesu glede mene in tebe v Kadeš Barnéi.',
        7: 'Štirideset let mi je bilo, ko me je Gospodov služabnik Mojzes poslal iz Kadeš Barnée, da ogledam deželo in ponovno sem mu prinesel besedo, kakor je bila ta v mojem srcu.',
        8: 'Kljub temu so moji bratje, ki so z menoj odšli gor, ljudstvu stopili srce, toda jaz sem v celoti sledil Gospodu, svojemu Bogu.',
        9: 'Mojzes je na ta dan prisegel, rekoč: ›Zagotovo bo dežela, ki si jo pomendral s svojimi stopali, tvoja dediščina in tvojih otrok na veke, ker si v celoti sledil Gospodu, mojemu Bogu.‹',
        10: 'Sedaj, glej, Gospod me je obdržal živega, kakor je rekel, teh petinštirideset let, celo odkar je Gospod spregovoril to besedo Mojzesu, medtem ko so Izraelovi otroci tavali po divjini. Sedaj glej, jaz sem danes star petinosemdeset let.',
        11: 'Še danes sem tako močan, kakor sem bil na dan, ko me je poslal Mojzes. Kakršna je bila moja moč takrat, celo takšna je moja moč za vojno zdaj, tako za odhajanje kakor za prihajanje.',
        12: 'Zdaj mi torej daj to goro, o kateri je Gospod govoril na tisti dan, kajti na tisti dan si slišal kako so bili tam Anákovci in da so bila mesta velika in ograjena. Če bo tako, da bo Gospod z menoj, potem jih bom zmožen pognati ven, kakor je rekel Gospod.«',
        13: 'Józue ga je blagoslovil in Jefunéjevemu sinu Kalébu v dediščino izročil Hebrón.',
        14: 'Hebrón je torej postal dediščina Jefunéjevega sina Kaléba, Kenázovca, do tega dne, zato ker je v celoti sledil Gospodu, Izraelovemu Bogu.',
        15: 'Ime Hebróna je bilo prej Kirját Arba; ta Arbá je bil velik mož med Anákovci. In dežela je imela počitek pred vojno.',
    },
    15: {
        1: 'To je bil torej žreb rodu Judovih otrok po njihovih družinah, celó do meje Edóma. Divjina Cin proti jugu je bila najskrajnejši del južne pokrajine.',
        2: 'Njihova južna meja je bila od obale slanega morja, od zaliva, ki gleda proti jugu',
        3: 'in ta je šla ven k južni strani Maleh-Akrabíma in šla vzdolž Cina in se dvignila na južno stran do Kadeš Barnée in šla vzdolž Hecróna in se dvignila do Adárja in po ovinkih šla do Karkoja.',
        4: 'Od tam je ta šla proti Acmónu in šla ven k egiptovski reki in izhodi te pokrajine so bili pri morju. To bo vaša južna pokrajina.',
        5: 'Vzhodna meja je bila slano morje, celó do konca Jordana. In njihova meja na severni četrtini je bila od morskega zaliva pri najbolj oddaljenem delu Jordana.',
        6: 'Meja se je dvignila k Bet Hogli in šla vzdolž ob severu Bet Arábe in meja se je dvignila do kamna Rubenovega sina Bohana.',
        7: 'Meja se je iz doline Ahór dvignila proti Debírju in tako proti severu, zroč proti Gilgálu, to je preden se vzpneš k Adumímu, ki je na južni strani reke. Meja je šla proti vodam En Šemeša in njihovi izhodi so bili pri En Rogelu.',
        8: '§ Meja se je dvignila pri dolini sina Hinómovega k južni strani Jebusejcev; isti je Jeruzalem. Meja se je dvignila k vrhu gore, ki leži pred Hinómovo dolino proti zahodu, ki je pri koncu doline velikanov proti severu',
        9: 'in meja je bila potegnjena od vrha hriba k vodnemu studencu Neftóaha in šla ven k mestom gore Efróna in meja je bila potegnjena k Baáli, ki je Kirját Jearím.',
        10: 'Meja je od Baále zavila proti zahodu, na gorovje Seír in šla vzdolž, do pobočja gore Jearím, ki je Kesalón, na severno stran in se spustila dol k Bet Šemešu in šla naprej do Timne.',
        11: 'Meja je šla ven k severni strani Ekróna in meja je bila potegnjena k Šikarónu in šla vzdolž do gore Baálo in šla ven k Jabneéli; in izhodi meje so bili pri morju.',
        12: 'Zahodna meja je bila do velikega morja in njegove pokrajine. To je pokrajina Judovih otrok naokoli, glede na njihove družine.',
        13: 'Jefunéjevemu sinu Kalébu je dal delež med Judovimi otroki, glede na Gospodovo zapoved Józuetu, torej mesto Arba, Anákovega očeta, ki je mesto Hebrón.',
        14: 'Kaléb je od tam pregnal tri Anákove sinove: Šešája, Ahimána in Talmája, Anákove otroke.',
        15: 'Od tam je odšel gor k prebivalcem Debírja. Ime Debírja je bilo prej Kirját Sefer.',
        16: 'Kaléb je rekel: »Kdor udari Kirját Sefer in ga zavzame, njemu bom dal svojo hčer Ahso za ženo.«',
        17: 'Zavzel ga je Kenázov sin Otniél, Kalébov brat in dal mu je svojo hčer Ahso za ženo.',
        18: 'Pripetilo se je, ko je prišla k njemu, da ga je primorala, da prosi od svojega očeta polje in razjahala je svojega osla in Kaléb ji je rekel: »Kaj hočeš?«',
        19: 'Ta je odgovorila: »Daj mi blagoslov, kajti dal si mi južno deželo; daj mi tudi vodne izvire.« In dal ji je gornje izvire in spodnje izvire.',
        20: 'To je dediščina rodu Judovih otrok glede na njihove družine.',
        21: 'Najbolj oddaljena mesta rodu Judovih otrok proti pokrajini Edóm, proti jugu, so bila: Kabceél, Eder, Jagúr,',
        22: 'Kina, Dimón, Adáda,',
        23: 'Kedeš, Hacór, Jitnán,',
        24: 'Zif, Telem, Bealót,',
        25: 'Hacór, Hadáta, Kerijót in Hecrón, ki je Hacór,',
        26: 'Amám, Šemaá, Moládaj,',
        27: 'Hacár Gada, Hešmón, Bet Pelet,',
        28: 'Hacár Šuál, Beeršéba, Bizjótja,',
        29: 'Baála, Ijím, Ecem,',
        30: 'Eltolád, Kesíl, Horma,',
        31: 'Ciklág, Madmaná, Sansána,',
        32: 'Lebaót, Šilhím, Ajin in Rimón. Vseh mest je devetindvajset, z njihovimi vasmi.',
        33: 'In v dolini Eštaól, Cora, Ašna,',
        34: 'Zanóah, En Ganím, Tapúah, Enájim,',
        35: 'Jarmút, Adulám, Sohó, Azéka,',
        36: 'Šaarájim, Aditájim, Gedêra in Gederotaim, štirinajst mest z njihovimi vasmi.',
        37: 'Cenán, Hadáša, Migdál Gad,',
        38: 'Dilán, Micpa, Jokteél,',
        39: 'Lahíš, Bockát, Eglón,',
        40: 'Kabón, Lahmás, Kitlíš,',
        41: 'Gederót, Bet Dagón, Naáma in Makéda; šestnajst mest z njihovimi vasmi.',
        42: 'Libna, Eter, Ašán,',
        43: 'Jiftáh, Ašna, Necíb,',
        44: 'Keíla, Ahzíb in Marešá; devet mest z njihovimi vasmi.',
        45: 'Ekrón z njegovimi mesti in njegovimi vasmi.',
        46: 'Od Ekróna, celo do morja, vse kar leži blizu Ašdóda, z njegovimi vasmi.',
        47: 'Ašdód z njegovimi mesti in njegovimi vasmi, Gaza s svojimi mesti in svojimi vasmi, do egiptovske reke in vélikega morja in njegove meje.',
        48: 'Na gorah: Šamír, Jatír, Sohó,',
        49: 'Dana, Kirját Sana, ki je Debír,',
        50: 'Anáb, Eštemóa, Aním,',
        51: 'Gošen, Holón in Gilo, enajst mest z njihovimi vasmi.',
        52: 'Aráb, Dumá, Ešán,',
        53: 'Janúm, Bet Tapúah, Aféka,',
        54: 'Humta, Kirját Arba, ki je Hebrón in Ciór, devet mest z njihovimi vasmi.',
        55: 'Maón, Karmel, Zif, Juta,',
        56: 'Jezreél, Jokdeám, Zanóah,',
        57: 'Kajin, Gíbei in Timna, deset mest z njihovimi vasmi.',
        58: 'Halhúl, Bet Cur, Gedór,',
        59: 'Maarát, Bet Anót in Eltekón, šest mest z njihovimi vasmi.',
        60: 'Kirját Báal, ki je Kirját Jearím in Raba, dve mesti z njunimi vasmi.',
        61: 'V divjini Bet Arába, Midín, Seháha,',
        62: 'Nibšán, Solno mesto in En Gedi, šest mest z njihovimi vasmi.',
        63: 'Kar se tiče Jebusejcev, prebivalcev Jeruzalema, jih Judovi otroki niso mogli pognati ven, temveč so Jebusejci prebivali z Judovimi otroki pri Jeruzalemu do današnjega dne.',
    },
    16: {
        1: 'Žreb Jožefovih otrok je padel od Jordana pri Jerihi, do vode Jerihe na vzhodu, k divjini, ki gre gor od Jerihe, čez goro Betel',
        2: 'in gre iz Betela v Luz in gre vzdolž do meja Arkičanov k Atarótu',
        3: 'in se spusti zahodno, k pokrajini Jaflétovcev, do pokrajine spodnjega Bet Horóna in do Gezerja in njeni izhodi so pri morju.',
        4: 'Tako sta Jožefova otroka, Manáse in Efrájim, vzela svojo dediščino.',
        5: 'Meja Efrájimovih sinov, glede na njihove družine, je bila takšna, torej meja njihove dediščine na vzhodni strani je bil Atrót Adár, do gornjega Bet Horóna',
        6: 'in meja je šla ven proti morju v Mihmetát na severni strani in meja je šla naokoli proti vzhodu v Taanát Šilo in šla poleg njega na vzhodu do Janóaha',
        7: 'in se spustila od Janóaha k Atarótu in k Naári in prišla k Jerihi in izšla pri Jordanu.',
        8: 'Meja je potekala od Tapúaha proti zahodu, k reki Kano in njeni izhodi so bili pri morju. To je dediščina rodu Efrájimovih otrok po njihovih družinah.',
        9: 'Oddvojena mesta za Efrájimove otroke so bila med dediščino Manásejevih otrok, vsa mesta z njihovimi vasmi.',
        10: 'Niso pa pregnali Kánaancev, ki so prebivali v Gezerju, temveč so Kánaanci prebivali med Efrájimci do današnjega dne in služili podvrženi plačevanju davka.',
    },
    17: {
        1: 'Tam je bil tudi žreb za Manásejev rod, kajti on je bil Jožefov prvorojenec. Namreč zaradi Manásejevega prvorojenca Mahírja, Gileádovega očeta, ker je bil bojevnik, zato je imel Gileád in Bašán.',
        2: 'Tam je bil tudi žreb za preostanek Manásejevih otrok po njihovih družinah za otroke Abiézerja in za otroke Heleka in za otroke Asriéla in za otroke Sihema in za otroke Heferja in za otroke Šemidája. To so bili dečki Manáseja, Jožefovega sina po njihovih družinah.',
        3: 'Toda Celofhád, sin Heferja, sin Gileáda, sin Mahírja, sin Manáseja, ni imel sinov, temveč hčere. To so imena njegovih hčera: Mahla, Noa, Hogla, Milka in Tirca.',
        4: 'Prišle so blizu, pred duhovnika Eleazarja in pred Nunovega sina Józueta in pred prince, rekoč: » Gospod je zapovedal Mojzesu, da nam daste dediščino med našimi brati.« Zato jim je glede na Gospodovo zapoved dal dediščino med brati njihovega očeta.',
        5: 'Tam je padlo deset deležev Manáseju, poleg gileádske in bašánske dežele, ki sta bili na drugi strani Jordana,',
        6: 'kajti Manásejeve hčere so imele dediščino med njegovimi sinovi. Preostanek Manásejevih sinov pa je imel deželo Gileád.',
        7: 'Manásejeva pokrajina je bila od Aserja do Mihmetáta, ki leži pred Sihemom. Meja je potekala vzdolž desne roke do prebivalcev En Tapúaha.',
        8: 'Torej Manáse je imel deželo Tapúah, toda Tapúah na Manásejevi meji je pripadal Efrájimovim otrokom',
        9: 'in pokrajina se je spustila k reki Kano, južno od reke; ta Efrájimova mesta so med Manásejevimi mesti. Tudi Manásejeve pokrajine so bile na severni strani reke in njihovi izhodi so bili pri morju.',
        10: 'Proti jugu je bilo Efrájimovo in proti severu je bilo Manásejevo in morje je njegova meja in na severu sta se srečala v Aserju in na vzhodu v Isahárju.',
        11: 'Manáse je imel v Isahárju in v Aserju Bet Šeán in njegova mesta, Jibleám in njegova mesta, prebivalce Dora in njegova mesta, prebivalce En Dora in njegova mesta, prebivalce Taanáha in njegova mesta in prebivalce Megída ter njegova mesta, torej tri dežele.',
        12: 'Vendar Manásejevi otroci niso mogli napoditi prebivalcev teh mest, temveč so v tej deželi hoteli prebivati Kánaanci.',
        13: 'Vendar se je pripetilo, ko so Izraelovi otroci postali močni, da so Kánaance podvrgli davku, toda niso jih popolnoma pognali ven.',
        14: 'Jožefovi otroci so spregovorili Józuetu, rekoč: »Zakaj si mi dal, da podedujem samo en žreb in en delež, glede na to, da sem veliko ljudstvo, ker me je Gospod doslej blagoslavljal?«',
        15: 'Józue jim je odgovoril: »Če si veliko ljudstvo, potem se dvigni v gozdnato deželo in tam posekaj zase, v deželi Perizéjcev in velikanov, če je gora Efrájim zate preozka.«',
        16: 'Jožefovi otroci so rekli: »Hrib ni dovolj za nas in vsi Kánaanci, ki prebivajo v dolinski deželi, imajo vozove iz železa, tako tisti, ki so iz Bet Šeána in njegovih mest in tisti, ki so iz doline Jezreél.«',
        17: 'Józue je spregovoril Jožefovi hiši, torej Efrájimu in Manáseju, rekoč: »Ti si veliko ljudstvo in imaš veliko moč. Ne boš imel samo enega deleža.',
        18: 'Toda gora bo tvoja, kajti to je les in ti ga boš posekal in dohodek od tega bo tvoj, kajti napodil boš Kánaance, čeprav imajo železne vozove in čeprav so močni.«',
    },
    18: {
        1: 'Celotna skupnost Izraelovih otrok se je zbrala skupaj pri Šilu in tam postavila šotorsko svetišče skupnosti. In dežela je bila podjarmljena pred njimi.',
        2: 'Tam je med Izraelovimi otroki ostalo sedem rodov, ki še niso prejeli svoje dediščine.',
        3: 'Józue je rekel Izraelovim otrokom: »Doklej se obirate, da greste, da vzamete v last deželo, ki vam jo je dal Gospod, Bog vaših očetov?',
        4: 'Dajte izmed sebe tri može za vsak rod in poslal jih bom in vstali bodo in šli skozi deželo in jo opisali glede na njihovo dediščino in ponovno bodo prišli k meni.',
        5: 'To bodo razdelili na sedem delov. Juda bo ostal v svojih pokrajinah na jugu in Jožefova hiša bo ostala v svojih pokrajinah na severu.',
        6: 'Vi boste torej opisali deželo v sedmih delih in opis prinesli sèm k meni, da lahko mečem žrebe za vas tukaj pred Gospodom, svojim Bogom.',
        7: 'Toda Lévijevci nimajo deleža med vami, kajti Gospodovo duhovništvo je njihova dediščina. Gad, Ruben in polovica Manásejevega rodu so prejeli svojo dediščino onkraj Jordana, na vzhodu, ki jim jo je dal Gospodov služabnik Mojzes.«',
        8: 'Možje so vstali ter odšli stran in Józue jim je naročil, da gredo, da opišejo deželo, rekoč: »Pojdite in hodite skozi deželo in jo opišite in ponovno pridite k meni, da bom tukaj v Šilu za vas lahko vrgel žrebe pred Gospodom.«',
        9: 'Možje so odšli in šli skozi deželo in jo v knjigi opisali po mestih v sedmih delih in ponovno prišli k Józuetu, k vojski pri Šilu.',
        10: 'Józue je zanje v Šilu metal žrebe pred Gospodom in tam je Józue Izraelovim otrokom razdelil deželo glede na njihove oddelke.',
        11: 'Žreb rodu Benjaminovih otrok je prišel gor glede na njihove družine in pokrajina njihovega žreba je prišla naprej med Judovimi otroki in Jožefovimi otroki.',
        12: 'Njihova meja na severni strani je bila od Jordana in meja je šla gor k strani Jerihe na severni strani in se dvigala skozi gore proti zahodu in njeni izhodi so bili pri divjini Bet Aven.',
        13: 'Meja je od tam šla preko, proti Luzu, k strani Luza, ki je Betel, proti jugu in meja se je spustila k Atrót Adárju, blizu hriba, ki leži na južni strani spodnjega Bet Horóna.',
        14: 'Meja je bila potegnjena od tam in obdala vogal morja proti jugu, od hriba, ki leži pred Bet Horónom proti jugu in njihovi izhodi so bili pri Kirját Báalu, ki je Kirját Jearím, mesto Judovih otrok. To je bila zahodna četrtina.',
        15: 'Južna četrtina je bila od konca Kirját Jearíma in meja se je nadaljevala na zahod in izšla pri izviru vodá Neftóaha',
        16: 'in meja se je spustila k vznožju gore, ki leži pred dolino sina Hinómovega in ki je v dolini velikanov na severu in se spustila k Hinómovi dolini, k strani Jebúsa na jugu in se spustila k En Rogelu',
        17: 'in potegnjena je bila od severa in šla naprej k En Šemešu in šla naprej proti Gelilótu, ki je nasproti vzpona k Adumímu in se spustila h kamnu Rubenovega sina Bohana',
        18: 'in šla naprej proti strani nasproti Arábi proti severu in se spustila k Arábi.',
        19: 'Meja je šla vzdolž strani Bet Hogle proti severu in izhodi meje so bili pri severnem zalivu slanega morja, pri južnem koncu Jordana. To je bila južna pokrajina.',
        20: 'Jordan je bil njegova meja na vzhodni strani. To je bila dediščina Benjaminovih otrok, po njihovih pokrajinah naokoli, glede na njihove družine.',
        21: 'Torej mesta rodov Benjaminovih otrok glede na njihove družine so bila Jeriha, Bet Hogla, dolina Kecíc,',
        22: 'Bet Arába, Cemarájim, Betel,',
        23: 'Avím, Para, Ofrá,',
        24: 'Kefár Amoní, Ofní in Gaba, dvanajst mest z njihovimi vasmi.',
        25: 'Gibeón, Rama, Beerót,',
        26: 'Micpa, Kefíra, Moca,',
        27: 'Rekem, Jirpeél, Tarála,',
        28: 'Cela, Elef, Jebús, kar je Jeruzalem, Gíbea in Kirját, štirinajst mest z njihovimi vasmi. To je dediščina Benjaminovih otrok glede na njihove družine.',
    },
    19: {
        1: 'Drugi žreb je prišel naprej k Simeonu, torej za rod Simeonovih otrok glede na njihove družine in njihova dediščina je bila znotraj dediščine Judovih otrok.',
        2: 'V svoji dediščini so imeli Beeršébo, ali Šebo in Moladáj,',
        3: 'Hacár Šuál, Baálo, Ecem,',
        4: 'Eltolád, Betúl, Hormo,',
        5: 'Ciklág, Bet Markabót, Hacár Susa,',
        6: 'Bet Lebaót in Šaruhén, trinajst mest in njihove vasi.',
        7: 'Ajin, Rimón, Eter in Ašán, štiri mesta in njihove vasi.',
        8: 'Vse vasi, ki so bile naokoli teh mest do Baalát Beêra, južnega Ramáta. To je dediščina rodu Simeonovih otrok glede na njihove družine.',
        9: 'Od deleža Judovih otrok je bila dediščina Simeonovih otrok, kajti delež Judovih otrok je bil zanje prevelik, zato so imeli Simeonovi otroci dediščino znotraj njihove dediščine.',
        10: 'Tretji žreb je prišel za Zábulonove otroke glede na njihove družine in meja njihove dediščine je bila do Sarída.',
        11: 'Njihova meja se je dvignila proti morju in Maráli in segla do Dabéšeta in segla do reke, ki je pred Jokneámom',
        12: 'in se obrnila od Saríde vzhodno proti vzhajanju sonca, k meji Kislót Tabora in potem je šla ven do Daberáta in šla gor k Jafíji',
        13: 'in od tam je šla vzdolž, na vzhodu do Gat Heferja k Et Kacínu in šla ven k Rimón-metoarju do Nea',
        14: 'in meja ga je obdala na severni strani do Hanatóna. Njeni izhodi so v dolini Jiftáh El.',
        15: 'Katát, Nahalál, Šimrón, Jidála in Betlehem, dvanajst mest z njihovimi vasmi.',
        16: 'To je dediščina Zábulonovih otrok glede na njihove družine, ta mesta z njihovimi vasmi.',
        17: 'Četrti žreb je izšel za Isahárja, za Isahárjeve otroke glede na njihove družine.',
        18: 'Njihova meja je bila proti Jezreélu, Kesulótu, Šunému,',
        19: 'Hafarájimu, Šiónu, Anaharátu,',
        20: 'Rabítu, Kišjónu, Ebecu,',
        21: 'Remetu, En Ganímu, En Hadu, Bet Pacécu',
        22: 'in pokrajina sega do Tabora, Šahacúma in Bet Šemeša. Izhodi njihove meje so bili pri Jordanu, šestnajst mest z njihovimi vasmi.',
        23: 'To je dediščina rodu Isahárjevih otrok glede na njihove družine, mesta in njihove vasi.',
        24: 'Peti žreb je izšel za rod Aserjevih otrok glede na njihove družine.',
        25: 'Njihova meja je bila Helkát, Halí, Beten, Ahšáf,',
        26: 'Alaméleh, Amád in Mišál in sega do Karmela proti zahodu in do Šihór Libnáta',
        27: 'in se obrača proti sončnemu vzhodu do Bet Dagóna in seže do Zábulona in k dolini Jiftáh El, proti severni strani Bet Emeka in Negiéla in gre ven na levi roki do Kabúla,',
        28: '§ Hebróna, Rehóba, Hamóna in Kane, celo k velikemu Sidónu',
        29: 'in potem se pokrajina obrne k Rami in k močnemu mestu Tir in pokrajina se obrne k Hosi. Njeni izhodi so pri morju od pokrajine do Ahzíba.',
        30: 'Tudi Uma, Afék in Rehób, dvaindvajset mest z njihovimi vasmi.',
        31: 'To je dediščina rodu Aserjevih otrok glede na njihove družine, ta mesta z njihovimi vasmi.',
        32: 'Šesti žreb je izšel za Neftálijeve otroke, torej za Neftálijeve otroke glede na njihove družine.',
        33: '§ Njihova pokrajina je bila od Helefa in Alóna do Caananíma in Adame, Nekeba in Jabneéla k Lakú in njeni izhodi so bili pri Jordanu.',
        34: 'Potem se pokrajina obrne proti zahodu k Aznót Taboru in od tam gre k Hukóku in sega do Zábulona na južni strani in do Aserja na zahodni strani in do Juda nad Jordanom proti sončnemu vzhodu.',
        35: 'Utrjena mesta so Cidím, Cer, Hamát, Rakát, Kinéret,',
        36: 'Adáma, Rama, Hacór,',
        37: 'Kedeš, Edréi, En Hacór,',
        38: 'Jirón, Migdál El, Horém, Bet Anát in Bet Šemeš. Devetnajst mest z njihovimi vasmi.',
        39: 'To je dediščina rodu Neftálijevih otrok glede na njihove družine, mesta in njihove vasi.',
        40: 'In sedmi žreb je izšel za rod Danovih otrok glede na njihove družine.',
        41: 'Pokrajina njihove dediščine je bila Cora, Eštaól, Ir Šemeš,',
        42: 'Šaalbím, Ajalón, Jitla,',
        43: 'Elón, Timna, Ekrón,',
        44: 'Elteké, Gibetón, Baalát,',
        45: 'Jehúd, Bené Berák, Gat Rimón,',
        46: '§ Me Jarkón in Rakon z mejo pred Jafo.',
        47: 'Pokrajina Danovih otrok je zanje izpadla premajhna, zato so Danovi otroci odšli gor, da se bojujejo zoper Lešem, ga zavzeli, ga udarili z ostrino meča, ga vzeli v last in tam prebivali in Lešem imenovali Dan, po imenu njihovega očeta Dana.',
        48: 'To je dediščina rodu Danovih otrok glede na njihove družine, ta mesta z njihovimi vasmi.',
        49: 'Ko so naredili konec razdeljevanju dežele za dediščino po njihovih pokrajinah, so Izraelovi otroci dali med njimi dediščino Nunovemu sinu Józuetu.',
        50: 'Glede na Gospodovo besedo so mu dali mesto, ki ga je prosil, torej Timnát Sêrah na gori Efrájim in zgradil je mesto ter tam prebival.',
        51: 'To so dediščine, ki so jih duhovnik Eleazar, Nunov sin Józue in poglavarji očetov rodov Izraelovih otrok v Šilu z žrebom razdelili v dediščino pred Gospodom, pri vratih šotorskega svetišča skupnosti. Tako so naredili konec razdeljevanju dežele.',
    },
    20: {
        1: 'Gospod je spregovoril tudi Józuetu, rekoč:',
        2: '»Govori Izraelovim otrokom, rekoč: ›Izločite si zavetna mesta, o katerih sem ti govoril po Mojzesovi roki,',
        3: 'da ubijalec, ki nenamerno in nevede ubije katerokoli osebo, lahko pobegne tja in ta bodo vaše zatočišče pred krvnim maščevalcem.',
        4: 'Ko bo tisti, ki pobegne v eno izmed teh mest, stal pri vhodu velikih vrat mesta in bo svojo zadevo oznanil v ušesa starešin tega mesta, ga bodo vzeli k sebi v mesto in mu dali prostor, da bo lahko prebival med njimi.',
        5: 'Če ga krvni maščevalec zasleduje, potem ubijalca ne bodo izročili v njegovo roko, ker je nevede udaril svojega bližnjega in ga predtem ni sovražil.',
        6: 'Prebival bo v tem mestu, dokler ne bo stal pred skupnostjo za sodbo in do smrti vélikega duhovnika, ki bo v tistih dneh. Potem se bo ubijalec vrnil in prišel v svoje lastno mesto in v svojo lastno hišo v mesto, iz katerega je pobegnil.‹«',
        7: 'Določili so Kedeš v Galileji, na gori Neftáli in Sihem na gori Efrájim in Kirját Arbo, ki je Hebrón, na Judovi gori.',
        8: 'Na drugi strani Jordana, pri Jerihi, proti vzhodu, so v divjini, na ravnini, določili Becer od Rubenovega rodu in Ramót v Gileádu od Gadovega rodu in Golán v Bašánu od Manásejevega rodu.',
        9: 'To so bila mesta, določena za vse Izraelove otroke in za tujca, ki začasno biva med njimi, da kdorkoli nenamerno ubije katerokoli osebo, lahko pobegne tja in ne umre po roki krvnega maščevalca, dokler ta stoji pred skupnostjo.',
    },
    21: {
        1: 'Potem so se približali poglavarji očetov Lévijevcev k duhovniku Eleazarju in k Nunovemu sinu Józuetu in k poglavarjem očetov rodov Izraelovih otrok',
        2: 'in jim govorili pri Šilu v kánaanski deželi, rekoč: » Gospod je po Mojzesovi roki zapovedal, da nam daste mesta, da prebivamo v [njih], z njihovimi predmestji, za našo živino.«',
        3: 'Izraelovi otroci so na Gospodovo zapoved dali Lévijevcem od svoje dediščine ta mesta in njihova predmestja.',
        4: 'Žreb je izšel za družine Kehátovcev in otroci duhovnika Arona, ki so bili izmed Lévijevcev, so imeli po žrebu od Judovega rodu, od Simeonovega rodu in od Benjaminovega rodu trinajst mest.',
        5: 'Preostali Kehátovi otroci so imeli po žrebu deset mest od družin iz Efrájimovega rodu, iz Danovega rodu in iz polovice Manásejevega rodu.',
        6: 'Geršónovi otroci so imeli po žrebu trinajst mest od Isahárjevega rodu, od Aserjevega rodu, od Neftálijevega rodu in od polovice Manásejevega rodu v Bašánu.',
        7: 'Meraríjevi otroci po njihovih družinah so imeli dvanajst mest od Rubenovega rodu, od Gadovega rodu in od Zábulonovega rodu.',
        8: 'Izraelovi otroci so po žrebu dali Lévijevcem ta mesta z njihovimi predmestji, kakor je Gospod zapovedal po Mojzesovi roki.',
        9: 'Ta mesta so dali od Judovega rodu in od Simeonovega rodu, ta mesta, ki so tukaj omenjena po imenu,',
        10: 'ki so jih imeli Aronovi otroci, ki so iz družine Kehátovcev, ki so bili izmed Lévijevih otrok, kajti njihov je bil prvi žreb.',
        11: 'Dali so jim mesto Arbá od Anákovega očeta; to mesto je Hebrón na hriboviti Judovi deželi, s predmestji okoli njega.',
        12: 'Toda polja mesta in njegove vasi so dali Jefunéjevemu sinu Kalébu za njegovo posest.',
        13: 'Tako so dali otrokom duhovnika Arona Hebrón z njegovimi predmestji, da bi bil zavetno mesto za ubijalca in Libno z njenimi predmestji,',
        14: 'Jatír z njegovimi predmestji, Eštemóa z njenimi predmestji,',
        15: 'Holón z njegovimi predmestji, Debír z njegovimi predmestji,',
        16: 'Ajin z njegovimi predmestji, Juto z njenimi predmestji in Bet Šemeš z njegovimi predmestji; devet mest od teh dveh rodov.',
        17: 'Iz Benjaminovega rodu Gibeón z njegovimi predmestji, Gebo z njenimi predmestji,',
        18: 'Anatót z njegovimi predmestji in Almon z njegovimi predmestji; štiri mesta.',
        19: 'Vseh mest Aronovih otrok, duhovnikov, je bilo trinajst mest z njihovimi predmestji.',
        20: 'Družine Kehátovih otrok, Lévijevci, ki so ostali izmed Kehátovih otrok, celo oni so imeli mesta od svojega žreba od Efrájimovega rodu.',
        21: 'Kajti dali so jim Sihem z njegovimi predmestji na gori Efrájim, da bo zavetno mesto za ubijalca, Gezer z njegovimi predmestji,',
        22: 'Kibcájim z njegovimi predmestji in Bet Horón z njegovimi predmestji; štiri mesta.',
        23: 'Od Danovega rodu, Elteké z njegovimi predmestji, Gibetón z njegovimi predmestji,',
        24: 'Ajalón z njegovimi predmestji in Gat Rimón z njegovimi predmestji; štiri mesta.',
        25: 'Od polovice Manásejevega rodu Taanáh z njegovimi predmestji in Gat Rimón z njegovimi predmestji; dve mesti.',
        26: 'Vseh mest je bilo deset, z njihovimi predmestji za družine Kehátovih otrok, ki so preostali.',
        27: 'Geršónovim otrokom iz družin Lévijevcev, iz druge polovice rodu Manáseja, so dali Golán v Bašánu z njegovimi predmestji, da bo zavetno mesto za ubijalca in Beastero z njenimi predmestji; dve mesti.',
        28: 'Iz Isahárjevega rodu Kišón z njegovimi predmestji, Daberát z njegovimi predmestji,',
        29: 'Jarmút z njegovimi predmestji in En Ganím z njegovimi predmestji; štiri mesta.',
        30: 'Iz Aserjevega rodu Mišál z njegovimi predmestji, Abdón z njegovimi predmestji,',
        31: 'Helkát z njegovimi predmestji in Rehób z njegovimi predmestji; štiri mesta.',
        32: 'Iz Neftálijevega rodu Kedeš v Galileji z njegovimi predmestji, da bo zavetno mesto za ubijalca, Hamót Dor z njegovimi predmestji in Kartán z njegovimi predmestji; tri mesta.',
        33: 'Vseh mest Geršónovcev, glede na njihove družine, je bilo trinajst mest z njihovimi predmestji.',
        34: 'Družinam Meraríjevih otrok, preostanku Lévijevcev iz Zábulonovega rodu, Jokneám z njegovimi predmestji, Kartán z njegovimi predmestji,',
        35: 'Dimno z njenimi predmestji in Nahalál z njegovimi predmestji; štiri mesta.',
        36: 'Iz Rubenovega rodu Becer z njegovimi predmestji, Jahac z njegovimi predmestji,',
        37: 'Kedemót z njegovimi predmestji in Mefáat z njegovimi predmestji; štiri mesta.',
        38: 'Iz Gadovega rodu Ramót v Gileádu z njegovimi predmestji, da bo zavetno mesto za ubijalca, Mahanájim z njegovimi predmestji,',
        39: 'Hešbón z njegovimi predmestji in Jazêr z njegovimi predmestji; skupaj štiri mesta.',
        40: 'Tako je bilo vseh mest za Meraríjeve otroke po njihovih družinah, ki so bili preostanek družin Lévijevcev, po njihovem žrebu, dvanajst mest.',
        41: 'Vseh mest Lévijevcev, znotraj posesti Izraelovih otrok je bilo oseminštirideset mest z njihovimi predmestji.',
        42: 'Ta mesta so bila vsako s svojimi predmestji naokoli njih; tako so bila vsa ta mesta.',
        43: 'Gospod je dal Izraelu vso deželo, ki jo je prisegel, da jo da njihovim očetom in vzeli so jo v last in v njej prebivali.',
        44: 'Gospod jim je dal počitek naokoli, glede na vse, kar je prisegel njihovim očetom in pred njimi ni obstal niti mož izmed vseh njihovih sovražnikov; Gospod je vse njihove sovražnike izročil v njihovo roko.',
        45: 'Tam ni manjkala nobena dobra stvar, ki jo je Gospod govoril Izraelovi hiši; vse so se izpolnile.',
    },
    22: {
        1: 'Potem je Józue poklical Rubenovce, Gádovce in polovico Manásejevega rodu',
        2: 'ter jim rekel: »Držali ste se vsega, kar vam je Gospodov služabnik Mojzes zapovedal in moj glas ste ubogali v vsem, kar sem vam zapovedal.',
        3: 'Te mnoge dni do tega dne niste zapustili svojih bratov, temveč ste skrbeli za zapoved Gospoda, svojega Boga.',
        4: 'Sedaj je Gospod, vaš Bog, dal počitek vašim bratom, kakor jim je obljubil, zato se sedaj vrnite in se odpravite v svoje šotore in v deželo svoje posesti, ki vam jo je dal Gospodov služabnik Mojzes na drugi strani Jordana.',
        5: 'Toda marljivo pazite, da izpolnite zapoved in postavo, ki vam jo je zapovedal Gospodov služabnik Mojzes, da ljubite Gospoda, svojega Boga in da hodite po vseh njegovih poteh in se držite njegovih zapovedi in da se mu trdno pridružite in mu služite z vsem svojim srcem in z vso svojo dušo.«',
        6: 'Tako jih je Józue blagoslovil in jih poslal proč; in odšli so k svojim šotorom.',
        7: 'Torej eni polovici Manásejevega rodu je Mojzes dal posest v Bašánu, toda drugi njegovi polovici je Józue dal [posest] med njihovimi brati na tej strani Jordana proti zahodu. Ko je Józue tudi njih poslal proč, v njihove šotore, tedaj jih je blagoslovil',
        8: 'in jim govoril, rekoč: »V svoje šotore se vrnite z mnogimi bogastvi in z zelo veliko živine, s srebrom in z zlatom, z bronom in z železom in z zelo mnogimi oblačili. Plen svojih sovražnikov razdelite s svojimi brati.«',
        9: 'Rubenovi otroci in Gadovi otroci in polovica Manásejevega rodu se je vrnila in odpotovala od Izraelovih otrok iz Šila, ki je v kánaanski deželi, da gredo v deželo Gileád, k zemlji njihove posesti, ki so jo vzeli v last, glede na Gospodovo besedo, po Mojzesovi roki.',
        10: 'Ko so prišli k mejam Jordana, ki so v kánaanski deželi, so Rubenovi otroci in Gadovi otroci in polovica Manásejevega rodu tam zgradili oltar pri Jordanu, na pogled velik oltar.',
        11: 'Izraelovi otroci so slišali reči: »Glejte, Rubenovi otroci, Gadovi otroci in polovica Manásejevega rodu so zgradili oltar nasproti kánaanski deželi, na mejah Jordana, ob prehodu Izraelovih otrok.«',
        12: 'Ko so Izraelovi otroci slišali o tem, se je celotna skupnost Izraelovih otrok skupaj zbrala pri Šilu, da gredo gor, da se vojskujejo proti njim.',
        13: 'Izraelovi otroci so k Rubenovim otrokom, h Gadovim otrokom in k polovici Manásejevega rodu v deželo Gileád poslali Pinhása, sina duhovnika Eleazarja',
        14: 'in z njim deset princev, iz vsake vodilne hiše princa, po vseh Izraelovih rodovih in vsak je bil poglavar svoje očetovske hiše med tisočerimi Izraelovimi.',
        15: 'Prišli so k Rubenovim otrokom, h Gadovim otrokom in k polovici Manásejevega rodu, v deželo Gileád in z njimi govorili, rekoč:',
        16: '»Tako govori celotna Gospodova skupnost: ›Kakšen prekršek je to, kar ste zagrešili zoper Izraelovega Boga, da se ta dan odvračate od sledenja Gospodu, v tem, da ste si zgradili oltar, da bi se ta dan lahko uprli zoper Gospoda?',
        17: 'Mar je krivičnost Peórja premajhna za nas, od katere do tega dne nismo očiščeni, čeprav je bila nadloga v Gospodovi skupnosti,',
        18: 'temveč da ste se ta dan morali odvrniti od sledenja Gospodu? Zgodilo se bo, glede na to, da ste se ta dan uprli zoper Gospoda, da bo jutri ogorčen nad celotno Izraelovo skupnostjo.',
        19: 'Vendar če je dežela vaše posesti nečista, potem prečkajte v deželo Gospodove posesti, v kateri prebiva Gospodovo šotorsko svetišče in vzemite posest med nami, toda ne uprite se zoper Gospoda niti se ne uprite zoper nas v tem, da si gradite oltar poleg oltarja Gospoda, našega Boga.',
        20: 'Mar ni Zerahov sin Ahán zagrešil prekršek v prekleti stvari in je bes padel na vso Izraelovo skupnost? In ta mož v svoji krivičnosti ni umrl sam.‹«',
        21: 'Potem so Rubenovi otroci, Gadovi otroci in polovica Manásejevega rodu odgovorili in rekli poglavarjem tisočerih Izraelovih:',
        22: '» Gospod, Bog bogov, Gospod, Bog bogov, on ve in Izrael bo vedel. Če je to v uporu ali če je v prestopku zoper Gospoda (ta dan nas ne reši),',
        23: 'da smo si zgradili oltar, da se obrnemo od sledenja Gospodu, ali če na njem darujemo žgalno daritev ali jedilno daritev ali če na njem žrtvujejo mirovne daritve, naj sam Gospod to zahteva',
        24: 'in če nismo tega raje storili zaradi strahu pred to stvarjo, rekoč: ›V času, ki pride, bodo vaši otroci lahko govorili našim otrokom, rekoč: ›Kaj imate z Gospodom, Izraelovim Bogom?',
        25: 'Kajti Gospod je naredil Jordan za mejo med nami in vami, vi Rubenovi otroci in Gadovi otroci, vi nimate deleža v Gospodu.‹‹ Tako bodo vaši otroci naredili našim otrokom, da se prenehajo bati Gospoda.',
        26: 'Zato smo rekli: ›Pripravimo se, da si zgradimo oltar, ne za žgalno daritev niti za klavno daritev,',
        27: 'temveč, da bo ta lahko priča med nami in vami in našimi rodovi za nami, da bomo lahko pred njim opravljali Gospodovo službo s svojimi žgalnimi daritvami, svojimi klavnimi daritvami in s svojimi mirovnimi daritvami,‹ da v času, ki pride, vaši otroci ne bodo mogli reči našim otrokom: ›Vi nimate deleža v Gospodu.‹',
        28: 'Zato smo rekli, da bo tako, ko bodo tako rekli nam ali našim rodovom, v času, ki pride, da bomo lahko ponovno rekli: ›Glejte vzorec Gospodovega oltarja, ki so ga naredili naši očetje, niti za žgalne daritve, niti za klavne daritve, temveč je ta priča med vami in nami.‹',
        29: 'Bog ne daj, da bi se uprli zoper Gospoda in se ta dan obrnili od sledenja Gospodu, da zgradimo oltar za žgalne daritve, za jedilne daritve ali za klavne daritve, poleg oltarja Gospoda, našega Boga, ki je pred njegovim šotorskim svetiščem.«',
        30: 'Ko so duhovnik Pinhás in princi skupnosti in poglavarji tisočerih Izraelovih, ki so bili z njim, slišali besede, ki so jih Rubenovi otroci, Gadovi otroci in Manásejevi otroci govorili, jim je to ugajalo.',
        31: 'In Pinhás, sin duhovnika Eleazarja, je rekel Rubenovim otrokom, Gadovim otrokom in Manásejevim otrokom: »Ta dan smo zaznali, da je med nami Gospod, zato ker tega prekrška niste zagrešili zoper Gospoda. Sedaj ste Izraelove otroke osvobodili iz Gospodove roke.«',
        32: 'Pinhás, sin duhovnika Eleazarja in princi so se vrnili od Rubenovih otrok in od Gadovih otrok iz dežele Gileád v kánaansko deželo, k Izraelovim otrokom in jim ponovno prinesli besedo.',
        33: 'Stvar je ugajala Izraelovim otrokom in Izraelovi otroci so blagoslovili Boga in niso nameravali iti gor zoper njih v bitko, da bi uničili deželo, v kateri so prebivali otroci Rubena in Gada.',
        34: 'Rubenovi otroci in Gadovi otroci pa so oltar imenovali Ed, kajti ta bo priča med nami, da Gospod je Bog.',
    },
    23: {
        1: 'Pripetilo se je, dolgo časa po tem, ko je Gospod dal počitek Izraelu pred vsemi njegovimi sovražniki naokoli, da je Józue postal star in zvrhan v starosti.',
        2: 'Józue je dal poklicati ves Izrael in po njihove starešine, po njihove poglavarje, po njihove sodnike, po njihove častnike ter jim rekel: »Star sem in zvrhan v starosti.',
        3: 'Videli ste vse, kar je Gospod, vaš Bog, zaradi vas storil vsem tem narodom, kajti Gospod, vaš Bog, je ta, ki se je boril za vas.',
        4: 'Glejte, z žrebom sem vam razdelil vse te narode, ki preostajajo, da bodo dediščina za vaše rodove, od Jordana, z vsemi narodi, ki sem jih iztrebil, celo do vélikega morja proti zahodu.',
        5: 'Gospod, vaš Bog, jih bo pregnal izpred vas in jih pognal iz vašega pogleda in vi boste vzeli v last njihovo deželo, kakor vam je Gospod, vaš Bog, obljubil.',
        6: 'Bodite torej zelo pogumni, da se držite in da storite vse, kar je zapisano v knjigi Mojzesove postave, da se ne obrnete vstran od tam ne k desni roki ne k levi,',
        7: 'da ne pridete med te narode, te, ki preostajajo med vami, niti ne omenjajte imena njihovih bogov, niti ne povzročajte, da prisegate pri njih, niti jim ne služite, niti se jim ne priklanjajte,',
        8: 'temveč se trdno pridružite Gospodu, svojemu Bogu, kakor ste storili ta dan.',
        9: 'Kajti Gospod je izpred vas pregnal velike in močne narode, toda glede vas, noben človek ni mogel obstati pred vami do tega dne.',
        10: 'En mož med vami jih bo pregnal tisoč, kajti Gospod, vaš Bog, on je ta, ki se bori za vas, kakor vam je obljubil.',
        11: 'Pazite torej nase, da ljubite Gospoda, svojega Boga.',
        12: 'Sicer če boste na kakršenkoli način šli nazaj in se trdno pridružili preostanku teh narodov, torej tem, ki preostajajo med vami in boste z njimi sklepali poroke in šli noter k njim in oni k vam,',
        13: 'zagotovo vedite, da Gospod, vaš Bog, izpred vas ne bo več pregnal nobenega izmed teh narodov, temveč vam bodo zanke, pasti in nadloge na vaših straneh in trni v vaših očeh, dokler ne izginete iz te dobre dežele, ki vam jo je dal Gospod, vaš Bog.',
        14: 'Glejte, ta dan grem pot vse zemlje in vi veste v vseh svojih srcih in v vseh svojih dušah, da se ni izjalovila niti ena od vseh dobrih stvari, ki jih je Gospod, vaš Bog, govoril glede vas. Vse so se vam zgodile in niti ena stvar od tega se ni izjalovila.',
        15: 'Zato se bo zgodilo, da kakor vse dobre stvari, ki so prišle nad vas, ki vam jih je Gospod, vaš Bog, obljubil, tako bo Gospod nad vas privedel vse zle stvari, dokler vas ne uniči iz te dobre dežele, ki vam jo je dal Gospod, vaš Bog.',
        16: 'Ko ste prekršili zavezo Gospoda, svojega Boga, ki vam jo je zapovedal in šli ter služili drugim bogovom in se jim priklanjali, potem bo zoper vas vžgana Gospodova jeza in hitro boste izginili iz dobre dežele, ki vam jo je dal.«',
    },
    24: {
        1: 'Józue je vse Izraelove rodove zbral v Sihem in dal poklicati po Izraelove starešine, po njihove poglavarje, po njihove sodnike in po njihove častnike in postavili so se pred Bogom.',
        2: 'Józue je vsemu ljudstvu rekel: »Tako govori Gospod, Izraelov Bog: ›Vaši očetje so v starih časih prebivali na drugi strani vèleréke, torej Terah, Abrahamov oče in Nahórjev oče in služili drugim bogovom.',
        3: 'Vzel sem vašega očeta Abrahama iz druge strani vèleréke in ga vodil skozi vso kánaansko deželo in pomnožil njegovo seme in mu dal Izaka.',
        4: 'Izaku sem dal Jakoba in Ezava. Ezavu sem dal gorovje Seír, da ga vzame v last, toda Jakob in njegovi otroci so odšli dol v Egipt.',
        5: 'Poslal sem tudi Mojzesa in Arona in Egipt udaril z nadlogami, glede na to, kar sem storil med njimi in potem sem vas privedel ven.',
        6: 'Vaše očete sem privedel iz Egipta in prišli ste k morju. Egipčani so vaše očete zasledovali z bojnimi vozovi in konjeniki do Rdečega morja.',
        7: 'Ko so klicali h Gospodu, je med vas in Egipčane postavil temo in nadnje privedel morje in jih pokril. Vaše oči so videle, kar sem storil v Egiptu in v divjini ste prebivali dolgo obdobje.',
        8: 'Privedel sem vas v deželo Amoréjcev, ki so prebivali na drugi strani Jordana. Borili so se z vami in izročil sem jih v vašo roko, da bi lahko vzeli v last njihovo deželo in uničil sem jih izpred vas.',
        9: 'Potem je Balák, Cipórjev sin, moábski kralj, vstal in se bojeval zoper Izrael in poslal ter poklical Beórjevega sina Bileáma, da vas prekolne,',
        10: 'toda nisem hotel prisluhniti Bileámu, zato vas je mirno blagoslovil. Tako sem vas osvobodil iz njegove roke.',
        11: 'Odšli ste čez Jordan in prišli do Jerihe. Zoper vas so se borili možje iz Jerihe [in] Amoréjci, Perizéjci, Kánaanci, Hetejci, Girgašéjci, Hivéjci in Jebusejci in izročil sem jih v vašo roko.',
        12: 'Pred vami sem poslal sršena, ki jih je pregnal izpred vas, celó dva kralja Amoréjcev, toda ne s tvojim mečem niti ne s tvojim lokom.',
        13: 'Dal sem vam deželo, za katero se niste trudili in mesta, ki jih niste zgradili, in vi prebivate v njih in jeste od vinogradov in oljčnih nasadov, ki jih niste sadili.‹',
        14: 'Zdaj se torej bojte Gospoda in mu služite v iskrenosti in resnici in odstranite bogove, ki so jim služili vaši očetje na drugi strani vèleréke in v Egiptu in služite Gospodu.',
        15: 'Če pa se vam to zdi zlo, da služite Gospodu, ta dan izberite komu boste služili: ali bogovom, ki so jim služili vaši očetje, ki so bili na drugi strani vèleréke, ali bogovom Amoréjcev, v čigar deželi prebivate. Toda kar se tiče mene in moje hiše, mi bomo služili Gospodu.«',
        16: 'Ljudstvo je odgovorilo in reklo: »Bog ne daj, da bi zapustili Gospoda, da služimo drugim bogovom,',
        17: 'kajti Gospod, naš Bog, on je ta, ki je nas in naše očete privedel gor iz egiptovske dežele, iz hiše sužnosti in ki je storil ta velika znamenja v našem pogledu in nas varoval po vsej poti, po kateri smo šli, in med vsem ljudstvom, skozi katero smo šli.',
        18: 'Gospod je izpred nas pregnal vse ljudstvo, celo Amoréjce, ki prebivajo v deželi. Zato bomo tudi služili Gospodu, kajti on je naš Bog.«',
        19: 'Józue je rekel ljudstvu: »Ne morete služiti Gospodu, kajti on je svet Bog; ljubosumen Bog je; ne bo odpustil vaših prestopkov niti vaših grehov.',
        20: 'Če zapustite Gospoda in služite tujim bogovom, potem se bo obrnil in vas prizadel in vas použil, potem ko vam je storil dobro.«',
        21: 'Ljudstvo je Józuetu reklo: »Ne, temveč bomo služili Gospodu.«',
        22: 'Józue je ljudstvu rekel: »Vi ste priče zoper vas same, da ste izbrali Gospoda, da mu služite.« Rekli so: » Mi smo priče.«',
        23: '»Zdaj torej odstranite,« je rekel, »tuje bogove, ki so med vami in svoje srce nagnite h Gospodu, Izraelovemu Bogu.«',
        24: 'Ljudstvo je Józuetu reklo: » Gospodu, našemu Bogu, bomo služili in njegov glas bomo ubogali.«',
        25: 'Tako je Józue tega dne sklenil zavezo z ljudstvom in jim postavil zakon in odredbo v Sihemu.',
        26: 'Józue je te besede zapisal v knjigo Božje postave in vzel velik kamen in ga tam postavil pod hrast, ki je bil poleg Gospodovega svetišča.',
        27: 'Józue je vsemu ljudstvu rekel: »Glejte, ta kamen nam bo priča, kajti ta je slišal vse Gospodove besede, ki nam jih je govoril. Ta vam bo zato priča, da ne bi zatajili svojega Boga.«',
        28: 'Tako je Józue ljudstvu pustil oditi, vsakemu možu v svojo dediščino.',
        29: 'Po vseh teh stvareh se je pripetilo, da je Nunov sin Józue, Gospodov služabnik, umrl, star sto deset let.',
        30: 'Pokopali so ga na meji njegove dediščine, v Timnát Serahu, ki je na gori Efrájim, na severni strani Gáaševega hriba.',
        31: 'Izrael je služil Gospodu vse Józuetove dni in vse dni starešin, ki so preživeli Józueta in ki so poznali vsa Gospodova dela, ki jih je storil za Izrael.',
        32: 'Jožefove kosti, ki so jih Izraelovi otroci prinesli gor iz Egipta, so pokopali v Sihemu, na parceli zemlje, ki jo je Jakob kupil od sinov Hamórja, Sihemovega očeta, za sto koščkov srebra in ta je postala dediščina Jožefovih otrok.',
        33: 'Aronov sin Eleazar je umrl in pokopali so ga na hribu, ki pripada njegovemu sinu Pinhásu, ki mu je bil dan na gori Efrájim.',
    },
}
